def send_desktop_notification(summary, body=""):
    """Envoie une notification desktop (backlog features.md §4.2 #109).

    Appel D-Bus direct a ``org.freedesktop.Notifications.Notify`` (spec
    freedesktop.org standard) via ``Gio`` — deja une dependance dure du
    projet (``from gi.repository import ... Gio ...`` plus haut), donc
    aucun nouveau paquet requis (pas de typelib ``Notify``/libnotify a
    installer, contrairement a l'approche `gi.repository.Notify`
    habituelle). Sans effet si ``conf.DISABLE_NOTIFICATIONS`` est actif
    (préférence dans « Préférences »), ou si aucun bus de session/démon de
    notifications n'est disponible (échec silencieux, journalisé en debug
    seulement — une notification manquée ne doit jamais interrompre une
    connexion ni faire planter l'appelant).

    Args:
        summary (str): Titre de la notification (deja traduit par l'appelant).
        body (str, optional): Corps du message (deja traduit). Defaults to "".
    """
    _loguru_logger.debug("send_desktop_notification: entrée")
    if conf.DISABLE_NOTIFICATIONS:
        app_logger.debug(
            "send_desktop_notification() returning | desactivee par conf.DISABLE_NOTIFICATIONS"
        )
        _loguru_logger.debug("send_desktop_notification: sortie")
        return
    try:
        bus = Gio.bus_get_sync(Gio.BusType.SESSION, None)
        bus.call_sync(
            "org.freedesktop.Notifications",
            "/org/freedesktop/Notifications",
            "org.freedesktop.Notifications",
            "Notify",
            GLib.Variant(
                "(susssasa{sv}i)",
                (_("Gnome Connection Manager"), 0, ICON_PATH, summary, body, [], {}, -1),
            ),
            GLib.VariantType.new("(u)"),
            Gio.DBusCallFlags.NONE,
            2000,
            None,
        )
        app_logger.debug(
            f"send_desktop_notification() returning | notification envoyee : {summary!r}"
        )
    except GLib.Error as e:
        app_logger.debug(
            f"send_desktop_notification() returning | bus/demon indisponible, ignoree : {e}"
        )
    except Exception as e:
        app_logger.warning(f"send_desktop_notification() | echec inattendu : {e}")
    _loguru_logger.debug("send_desktop_notification: fin")


def _launch_hook_command(command, source):
    """Lance (ou ignore) une commande "hook" avant/après connexion déjà résolue.

    Fonction partagée par ``run_pre_connect_hook()`` (appel direct, host en
    main) et par le hook "après connexion" (résolu à l'ouverture de l'onglet,
    voir ``_open_connection_tab()``/``addTab()``, puis lancé plus tard par
    ``widgets.NotebookTabLabel.mark_tab_as_closed()`` — d'où la séparation
    entre résolution et lancement : au moment où l'onglet se ferme, l'objet
    ``Host`` d'origine n'est plus disponible, seule la commande déjà résolue
    l'est). Lancée en tâche de fond (``subprocess.Popen``, ``shell=True``,
    sans attendre sa fin ni vérifier son code de sortie) pour ne jamais
    retarder ni bloquer l'ouverture/fermeture de la connexion : un hook lent,
    mal écrit ou en échec ne doit jamais gêner l'utilisateur. Échec de
    lancement journalisé en warning seulement, jamais remonté à
    l'utilisateur — même philosophie que ``send_desktop_notification()``.

    Args:
        command (str | None): Commande déjà résolue (marqueurs substitués),
            ou ``None`` si aucun hook n'est configuré (rien à faire).
        source (str): Nom du point d'appel, pour le message de log
            (ex. ``"run_pre_connect_hook"``,
             ``"NotebookTabLabel.mark_tab_as_closed (post_connect)"``).

    Returns:
        None: Cette fonction ne retourne rien de significatif.
    """
    _loguru_logger.debug("_launch_hook_command: entrée")
    if command is None:
        app_logger.debug(
            f"_launch_hook_command() returning | {source} : aucune commande a executer"
        )
        _loguru_logger.debug("_launch_hook_command: sortie")
        return
    try:
        subprocess.Popen(command, shell=True)
        app_logger.debug(
            f"_launch_hook_command() returning | {source} : commande lancee : {command!r}"
        )
    except Exception as e:
        app_logger.warning(f"_launch_hook_command() | {source} : echec de lancement, ignore : {e}")
    _loguru_logger.debug("_launch_hook_command: fin")


def run_pre_connect_hook(host):
    """Lance la commande "avant connexion" de l'hôte, si renseignée (#116).

    Backlog features.md §4.2, "Scripting avant/après connexion" — les deux
    volets sont faits : le volet "après" (``Host.post_connect_command``) est
    résolu à l'ouverture de l'onglet (voir ``_open_connection_tab()``/
    ``addTab()``) puis lancé à la fermeture par
    ``widgets.NotebookTabLabel.mark_tab_as_closed()``, seul point
    d'accroche commun disponible ("connexion terminée") — couvre donc les
    protocoles VTE (SSH/telnet/local/serial/ipmi) uniquement, contrairement
    à ce hook "avant" qui est générique à tout protocole.

    Résolution des marqueurs ``{name}``/``{address}``/``{group}``/
    ``{protocol}`` déléguée à la fonction pure
    ``gcm4_core.resolve_connection_hook_command()`` (testable sans stub
    GTK). Câblée une seule fois, en tête de ``Wmain._open_connection_tab()``
    — point d'entrée générique unique quel que soit le protocole (SSH, RDP,
    VNC, SPICE, série, telnet, local...), contrairement à
    ``send_desktop_notification()`` qui ne couvre que les protocoles VTE via
    le signal ``child-exited``.

    Args:
        host (Host): Hôte pour lequel la connexion s'ouvre.
            ``host.pre_connect_command`` est le modèle de commande brut
            saisi dans "Éditer hôte" (chaîne vide = aucun hook).

    Returns:
        None: Cette fonction ne retourne rien de significatif.
    """
    _loguru_logger.debug("run_pre_connect_hook: entrée")
    template = getattr(host, "pre_connect_command", "") or ""
    app_logger.debug(
        f"run_pre_connect_hook() called | host={getattr(host, 'name', '?')!r} "
        f"template={template!r}"
    )
    command = gcm4_core.resolve_connection_hook_command(
        template,
        host_name=getattr(host, "name", "") or "",
        host_address=getattr(host, "host", "") or "",
        host_group=getattr(host, "group", "") or "",
        protocol=getattr(host, "protocol", "") or "",
    )
    _launch_hook_command(command, "run_pre_connect_hook")
    _loguru_logger.debug("run_pre_connect_hook: fin")


def resolve_post_connect_command(host, proto):
    """Résout la commande "après connexion" de l'hôte pour un futur lancement.

    Contrepartie de ``run_pre_connect_hook()`` pour le volet "après" (#116) :
    contrairement au hook "avant" (résolu ET lancé immédiatement, l'objet
    ``Host`` étant sous la main), le hook "après" doit être lancé plus tard,
    quand la connexion se termine — moment où ``widgets.NotebookTabLabel``
    ne connaît plus l'objet ``Host`` d'origine (voir
    ``host_auto_close_tab``, même limitation). La résolution des marqueurs
    ``{name}``/``{address}``/``{group}``/``{protocol}`` se fait donc ici,
    tout de suite, et la commande déjà résolue est propagée à travers les 5
    sites de création de ``NotebookTabLabel`` (même chantier que
    ``host_auto_close_tab``) pour être lancée plus tard par
    ``_launch_hook_command()`` depuis
    ``NotebookTabLabel.mark_tab_as_closed()``.

    Args:
        host (Host): Hôte pour lequel la connexion s'ouvre.
        proto (str): Protocole de l'hôte (substitué à ``{protocol}``).

    Returns:
        str | None: Commande résolue, ou ``None`` si aucun hook n'est
        configuré pour cet hôte.
    """
    return gcm4_core.resolve_connection_hook_command(
        getattr(host, "post_connect_command", "") or "",
        host_name=getattr(host, "name", "") or "",
        host_address=getattr(host, "host", "") or "",
        host_group=getattr(host, "group", "") or "",
        protocol=proto or "",
    )


