def _serial_templates_load(cp):
    """Charge les templates série depuis le ConfigParser.

    Vestige de protocole assumé (2026-08-30) : les templates série
    (presets Cisco/Huawei/Arduino...) sont des données spécifiques au
    protocole série — elles n'ont pas leur place dans gcm4_core.py (cœur
    neutre de protocole). Elles restent ici pour l'instant, comme
    ``plugins/plugin_serial.py`` (qui maintient sa propre copie
    indépendante non synchronisée — bug distinct, voir features.md §2.8) ;
    les deux migreront vers plugins/serial/ quand ce sera son tour dans le
    découpage en dossiers (SSH est le plugin pilote, pas série).

    Args:
        cp (configparser.RawConfigParser): Objet de configuration déjà lu.

    Returns:
        bool: True si la section a été trouvée et traitée, False sinon.
    """
    _loguru_logger.debug("_serial_templates_load: entrée")
    global _SERIAL_TEMPLATES
    if not cp.has_section("serial_templates"):
        _SERIAL_TEMPLATES = dict(_SERIAL_TEMPLATES_DEFAULT)
        _loguru_logger.debug("_serial_templates_load: sortie")
        return False
    _SERIAL_TEMPLATES = dict(_SERIAL_TEMPLATES_DEFAULT)
    for name, value in cp.items("serial_templates"):
        original_name = name
        for k in _SERIAL_TEMPLATES_DEFAULT:
            if k.lower() == name.lower():
                original_name = k
                break
        parts = [p.strip() for p in value.split(",")]
        if len(parts) == 5:
            _SERIAL_TEMPLATES[original_name] = tuple(parts)
    _loguru_logger.debug("_serial_templates_load: sortie")
    return True


def _serial_templates_save(cp):
    """Écrit la section [serial_templates] dans le ConfigParser.

    Voir _serial_templates_load() pour la note sur ce vestige assumé.

    Args:
        cp (configparser.RawConfigParser): Objet de configuration à mettre à jour.
    """
    _loguru_logger.debug("_serial_templates_save: entrée")
    if cp.has_section("serial_templates"):
        cp.remove_section("serial_templates")
    cp.add_section("serial_templates")
    for name, tpl in _SERIAL_TEMPLATES.items():
        cp.set("serial_templates", name, ",".join(tpl))
    _loguru_logger.debug("_serial_templates_save: fin")


def get_serial_templates():
    """Retourne une copie des templates série actuellement chargés."""
    return dict(_SERIAL_TEMPLATES)


