class Wmain(GCMBase, Gtk.Window):
    """Fenêtre principale — deuxième écran converti du Glade vers Python pur.

    Écran 100% Python (plus de chargement de ``wMain`` depuis
    ``gnome-connection-manager.glade``) : hérite directement de
    ``Gtk.Window`` (mode ``path=None`` de ``GCMBase``, même pattern que
    ``Wabout``/``SSHKeyManagerDialog``).

    Reconstruction fidèle de l'arbre de widgets défini par le noeud
    ``wMain`` du ``.glade`` : ``GtkBox`` vertical contenant le bouton de
    menu principal (``btnPrimaryMenu``), la barre de recherche cachée par
    défaut (``searchBar`` / ``txtSearch`` / ``btnSearchBack`` /
    ``btnSearchForward``), puis le ``GtkPaned`` (``hpMain``) séparant
    l'arbre des serveurs (``treeServers``) du notebook de sessions
    (``nbConsole``). Les deux pages de démo présentes dans le ``.glade``
    (uniquement là pour éviter un avertissement GTK au design) ne sont pas
    recréées ici : le code existant les supprimait déjà au démarrage
    (cf. plus bas, "Just added children in glade...").

    Fidélité : le reste de cette (très grosse) classe accède aux widgets
    via ``self.get_widget("...")`` ou des attributs déjà normalisés
    (``self.wMain``, ``self.hpMain``, ``self.nbConsole``,
    ``self.treeServers``, ``self.window``) — plutôt que de modifier des
    dizaines d'appels dispersés dans tout le fichier, ``get_widget()`` est
    surchargé pour puiser dans ``self._widgets``, qui ne contient que les
    identifiants réellement présents dans le noeud ``wMain`` d'origine
    (comportement inchangé : un id absent du sous-arbre Glade d'origine —
    ex. ``mnu_dark_mode``, qui n'a jamais existé dans le ``.glade`` —
    retourne toujours ``None``, exactement comme avant).
    """

    def __init__(self, **kwargs):
        """Construit la fenêtre principale (widgets, signaux, état)."""
        _loguru_logger.debug("__init__: entrée")
        Gtk.Window.__init__(self)
        GCMBase.__init__(self, path=None, **kwargs)
        self.main_widget = self

        self.set_title(_("Gnome Connection Manager"))
        self.set_destroy_with_parent(True)
        self.set_icon_from_file(ICON_PATH)

        vbox = Gtk.Box(orientation=Gtk.Orientation.VERTICAL)
        vbox.show()
        self.add(vbox)

        btnPrimaryMenu = Gtk.MenuButton()
        btnPrimaryMenu.set_tooltip_text(_("Menu"))
        btnPrimaryMenu.set_halign(Gtk.Align.START)
        btnPrimaryMenu.set_use_popover(True)
        img_menu = Gtk.Image.new_from_icon_name("open-menu-symbolic", Gtk.IconSize.BUTTON)
        img_menu.show()
        btnPrimaryMenu.add(img_menu)
        btnPrimaryMenu.show()
        vbox.pack_start(btnPrimaryMenu, False, True, 0)

