    def get_widget(self, name):
        """Retourne le widget identifie par name.

        Remplace l'implementation ``GCMBase.get_widget`` (qui interroge
        ``self.builder``, absent ici puisque ``wMain`` est construit en
        Python pur) : puise dans ``self._widgets``, qui ne contient que les
        identifiants presents dans le noeud ``wMain`` du ``.glade``
        d'origine. Un id absent (ex. ``mnu_dark_mode``, qui n'existait deja
        pas dans le ``.glade``) retourne ``None``, exactement comme avant.

        Args:
            name (str): Nom du widget.

        Returns:
            Gtk.Widget or None: Widget trouve ou None.
        """
        return self._widgets.get(name)

    def update_visual(self):
        """Met a jour les proprietes visuelles de la fenetre principale."""
        _loguru_logger.debug("update_visual: entrée")
        window = self.get_widget("wMain")
        screen = window.get_screen()
        visual = screen.get_rgba_visual()
        if visual and screen.is_composited():
            # NOTE: We should re-realize window when update window visual
            # Otherwise it may failed, when the gcm is started without compositor
            window.unrealize()
            window.set_visual(visual)
            window.transparency = True
            window.realize()
            if window.get_property("visible"):
                window.hide()
                window.show()
        else:
            sys.stderr.write("System doesn't support transparency\n")
            window.transparency = False
            window.set_visual(screen.get_system_visual())
        _loguru_logger.debug("update_visual: fin")

    def enable_window_transparency(self, window):
        # hack to allow transparent widgets inside a opaque window
        # the key is to set the alpha channel of the window's background color to
        # 0.9999, in that way the window is opaque but still allows transparent
        # children

        # remove previously addded css to get the background color from the current gtk theme
        """Active ou desactive la transparence de la fenetre si le compositeur le permet.

        Args:
            window: Parametre window.
        """
        _loguru_logger.debug("enable_window_transparency: entrée")
        if hasattr(window, "style_provider") and window.style_provider:
            Gtk.StyleContext.remove_provider_for_screen(
                Gdk.Screen.get_default(), window.style_provider
            )

        # get window background color — fix: get_background_color est deprecie en GTK3 recent,
        # on utilise lookup_color() avec fallback sur une couleur neutre
        context = window.get_style_context()
        found, color = context.lookup_color("theme_bg_color")
        if not found:
            found, color = context.lookup_color("bg_color")
        if not found:
            color = Gdk.RGBA()
            color.parse("#f0f0f0")

        # set the background color to the same as the gtk theme, but with alpha
        # 0.99999 (it looks opaque but allows to have transparent widgets)
        CSS = b"""
        window.background {
            background-color: rgba(%d, %d, %d, %f);
        }
        """ % (
            color.red * 255,
            color.green * 255,
            color.blue * 255,
            0.999999,
        )

        window.style_provider = Gtk.CssProvider()
        window.style_provider.load_from_data(CSS)

        context.add_provider_for_screen(
            window.get_screen(),
            window.style_provider,
            Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION,
        )
        _loguru_logger.debug("enable_window_transparency: fin")

