    # -- Wmain.attach_terminal_click_gesture {
    def attach_terminal_click_gesture(self, widget):
        """Attache le geste de clic (menu contextuel/URL) a un terminal VTE.

        Remplace, depuis la session-40, l'ancien branchement de
        ``on_terminal_click`` sur le signal ``button-press-event`` (2 sites
        d'appel identiques, voir ``docs/gtk4-migration.md`` §3.6-nonies)
        par un ``Gtk.GestureMultiPress`` par terminal, meme
        principe que ``self._tree_servers_press_gesture`` (session-39) mais
        adapte a un widget cree dynamiquement (un terminal par onglet,
        contrairement a ``treeServers``, unique et statique) : la reference
        au geste est conservee directement sur le widget lui-meme
        (``widget._terminal_click_gesture``), pas sur ``self`` — sa duree
        de vie suit ainsi naturellement celle du terminal (collectee quand
        l'onglet est ferme) plutot que de s'accumuler indefiniment sur
        ``Wmain`` a chaque nouvelle connexion.

        Args:
            widget (Vte.Terminal): Terminal fraichement cree, sur lequel
                brancher le geste (appele aux deux sites de creation d'un
                terminal — connexions via plugin et console RDP heritee).
        """
        app_logger.debug(f"attach_terminal_click_gesture() called | widget={widget!r}")
        gesture = Gtk.GestureMultiPress.new(widget)
        # Bouton 0 = ecoute tous les boutons (defaut GTK : bouton 1 seul) —
        # necessaire ici car classify_terminal_click() distingue elle-meme
        # clic droit (menu/coller) et clic gauche (detection d'URL sous
        # Ctrl), comme le faisait l'ancien gestionnaire unique sur
        # button-press-event. Meme raisonnement que
        # self._tree_servers_press_gesture (session-39).
        gesture.set_button(0)
        # Phase TARGET (et non BUBBLE, la valeur par defaut) : meme point
        # d'entree que l'ancien "button_press_event" connecte directement
        # sur le terminal, avant le traitement par defaut de Vte.Terminal
        # (selection de texte, notamment le mot/ligne au double/triple-clic
        # — volontairement laisse intact, voir classify_terminal_click()).
        gesture.set_propagation_phase(Gtk.PropagationPhase.TARGET)
        gesture.connect("pressed", self.on_terminal_pressed, widget)
        widget._terminal_click_gesture = gesture
        app_logger.debug("attach_terminal_click_gesture() returning")

    # -- Wmain.attach_terminal_click_gesture }

    # -- Wmain.on_terminal_pressed {
    def on_terminal_pressed(self, gesture, n_press, x, y, widget):
        """Gestionnaire de clic sur un terminal VTE (Gtk.GestureMultiPress).

        Remplace, depuis la session-40, l'ancien gestionnaire
        ``on_terminal_click`` connecte au signal ``button-press-event`` sur
        ``Gdk.EventButton`` — voir ``docs/gtk4-migration.md`` §3.6-nonies
        pour le detail du portage et la correspondance exacte avec l'ancien
        comportement (:func:`gesture_trigger_core.classify_terminal_click`).
        Deuxieme des trois sites identifies par l'audit session-38, apres
        ``treeServers``/``popupMenuFolder`` (session-39).

        Args:
            gesture (Gtk.GestureMultiPress): Geste a l'origine du signal
                ``pressed``, attache au terminal via
                :meth:`attach_terminal_click_gesture` avec
                ``set_button(0)`` (tous boutons).
            n_press (int): Nombre de pressions consecutives (1 = clic
                simple, 2 = double clic, 3 = triple clic).
            x (float): Coordonnee X du clic, relative a ``widget``.
            y (float): Coordonnee Y du clic, relative a ``widget``.
            widget (Vte.Terminal): Terminal cible, passe explicitement a la
                connexion du signal plutot que retrouve via ``gesture`` —
                ``Gtk.GestureSingle`` n'expose pas directement son widget
                surveille en GTK3 (a la difference de
                ``self._tree_servers_press_gesture``, qui garde sa propre
                reference car il n'existe qu'un seul ``treeServers``).
        """
        _loguru_logger.debug("on_terminal_pressed: entrée")
        button = gesture.get_current_button()
        app_logger.debug(
            f"on_terminal_pressed() called | button={button!r} n_press={n_press!r} "
            f"x={x!r} y={y!r} widget={widget!r}"
        )
        # get_current_event_state()/get_current_event() n'existent pas en
        # GTK3 (ajouts GTK4 uniquement, voir la correction session-39,
        # docs/gtk4-migration.md §3.6-octies) — get_last_event(None) est
        # l'equivalent GTK3 pour retrouver l'evenement complet (etat des
        # modificateurs, et ici aussi les coordonnees attendues par
        # match_check_event()/hyperlink_check_event()).
        event = gesture.get_last_event(None)
        # get_state() renvoie selon la version de PyGObject soit les flags
        # seuls, soit un tuple résultat (succès, état) — le « & » direct lève
        # TypeError sur PyGObject récent (bug exposé par la vérification
        # empirique de l'issue #72, voir docs/gtk4-migration.md
        # §3.6-quaterdecies) ; masque_actif_dans_etat() normalise les deux.
        ctrl_pressed = bool(
            event is not None
            and masque_actif_dans_etat(event.get_state(), Gdk.ModifierType.CONTROL_MASK)
        )
        outcome = classify_terminal_click(
            button=button,
            n_press=n_press,
            ctrl_pressed=ctrl_pressed,
            paste_on_right_click=conf.PASTE_ON_RIGHT_CLICK,
        )
        if outcome == "paste":
            widget.paste_clipboard()
            app_logger.debug("on_terminal_pressed() returning | outcome='paste'")
            _loguru_logger.debug("on_terminal_pressed: sortie")
            return
        if outcome == "open-menu":
            nb = widget.get_parent().get_parent()
            self.popupMenu.terminal = widget
            self.popupMenu.rebuild(
                has_selection=widget.get_has_selection(),
                multi_pane=nb.get_n_pages() > 1,
                has_split_notebook=self.find_notebook(self.hpMain, self.nbConsole) is not None,
                log_active=hasattr(widget, "log_handler_id") and widget.log_handler_id != 0,
            )
            self.popupMenu.popup_at(widget, x, y)
            app_logger.debug("on_terminal_pressed() returning | outcome='open-menu'")
            _loguru_logger.debug("on_terminal_pressed: sortie")
            return
        if outcome == "check-url" and event is not None:
            url, tag = widget.match_check_event(event)
            if tag == widget.tag_url:
                url = "http://%s" % url
            elif tag == widget.tag_email and not url.startswith("mailto:"):
                url = "mailto://%s" % url
            url = url or widget.hyperlink_check_event(event)
            if url:
                Gtk.show_uri(Gdk.Screen.get_default(), url, Gtk.get_current_event_time())
        # terminal doesnt emmit the "focus" signal when there is more than one
        # visible on the screen, so force the focus
        nb = widget.get_parent().get_parent()
        self.on_tab_focus(nb, nb.get_nth_page(nb.get_current_page()), nb.get_current_page())
        app_logger.debug(f"on_terminal_pressed() returning | outcome={outcome!r}")
        _loguru_logger.debug("on_terminal_pressed: fin")

    # -- Wmain.on_terminal_pressed }

    def on_terminal_keypress(self, widget, event, *args):
        # if shortcuts.has_key(get_key_name(event)):
        """Gestionnaire de touche pressee dans un terminal VTE.

        Args:
            widget (Vte.Terminal): Terminal source.
            event (Gdk.EventKey): Evenement clavier.
            *args: Arguments supplementaires (ignorés).
        """
        _loguru_logger.debug("on_terminal_keypress: entrée")
        if conf.DISABLE_SHORTCUTS:
            # Préférence "Désactiver les raccourcis clavier" (backlog §4.2,
            # urgence faible) : toutes les combinaisons de `shortcuts`
            # (standard ET custom, même dict, voir loadConfig()) sont
            # ignorées et chaque touche part directement au terminal/session
            # distante — utile quand une combinaison entre en conflit avec
            # une application distante (ex. Ctrl+Tab utilisé par l'appli
            # distante elle-même).
            _loguru_logger.debug("on_terminal_keypress: sortie")
            return False
        if get_key_name(event) in shortcuts:
            cmd = shortcuts[get_key_name(event)]
            if isinstance(cmd, list):
                # comandos predefinidos
                if cmd == _COPY:
                    self.terminal_copy(widget)
                elif cmd == _PASTE:
                    self.terminal_paste(widget)
                elif cmd == _COPY_ALL:
                    self.terminal_copy_all(widget)
                elif cmd == _SAVE:
                    self.show_save_buffer(widget)
                elif cmd == _FIND:
                    self.get_widget("searchBar").show()
                    self.get_widget("txtSearch").select_region(0, -1)
                    self.get_widget("txtSearch").grab_focus()
                elif cmd == _FIND_NEXT:
                    if hasattr(self, "search"):
                        self.find_word()
                elif cmd == _CLEAR:
                    widget.reset(True, True)
                elif cmd == _FIND_BACK:
                    if hasattr(self, "search"):
                        self.find_word(backwards=True)
                elif cmd == _CLONE:
                    term = widget
                    ntbk = widget.get_parent().get_parent()
                    tab = ntbk.get_tab_label(term.get_parent())
                    if not hasattr(term, "host"):
                        self.addTab(ntbk, tab.get_text())
                    else:
                        host = term.host.clone()
                        host.name = tab.get_text()
                        host.log = hasattr(term, "log_handler_id") and term.log_handler_id != 0
                        self.addTab(ntbk, host)
                elif cmd == _CONSOLE_PREV:
                    ntbk = widget.get_parent().get_parent()
                    if ntbk.get_current_page() == 0 and conf.CYCLE_TABS:
                        ntbk.set_current_page(len(ntbk) - 1)
                    else:
                        ntbk.prev_page()
                elif cmd == _CONSOLE_NEXT:
                    ntbk = widget.get_parent().get_parent()
                    if ntbk.get_current_page() == len(ntbk) - 1 and conf.CYCLE_TABS:
                        ntbk.set_current_page(0)
                    else:
                        ntbk.next_page()
                elif cmd == _FULLSCREEN:
                    if self._current_fullscreen_state:
                        Gtk.Window.unfullscreen(self.hpMainWindow)
                        Gtk.Window.unfullscreen(self.wMainWindow)
                        self.wMainWindow.set_decorated(True)
                        pass  # set_has_resize_grip déprécié GTK 3.14
                        self.get_widget("btnPrimaryMenu").show()
                        self._current_fullscreen_state = False
                    else:
                        Gtk.Window.fullscreen(self.hpMainWindow)
                        self.wMainWindow.set_decorated(False)
                        pass  # set_has_resize_grip déprécié GTK 3.14
                        Gtk.Window.fullscreen(self.wMainWindow)
                        self.get_widget("btnPrimaryMenu").hide()
                        self._current_fullscreen_state = True

                elif cmd == _CONSOLE_CLOSE:
                    wid = widget.get_parent()
                    page = widget.get_parent().get_parent().page_num(wid)
                    if page != -1:
                        widget.get_parent().get_parent().remove_page(page)
                        wid.destroy()
                elif cmd == _CONSOLE_RECONNECT:
                    if not hasattr(widget, "command"):
                        # widget.fork_command(SHELL)
                        vte_run(widget, SHELL)
                    else:
                        # widget.fork_command(widget.command[0], widget.command[1])
                        vte_run(widget, widget.command[0], widget.command[1])
                        while Gtk.events_pending():
                            Gtk.main_iteration()

                        # esperar 2 seg antes de enviar el pass para dar tiempo a que se levante
                        # expect y prevenir que se muestre el pass
                        if widget.command[2] is not None and widget.command[2] != "":
                            GLib.timeout_add(2000, self.send_data, widget, widget.command[2])
                    widget.get_parent().get_parent().get_tab_label(
                        widget.get_parent()
                    ).mark_tab_as_active()
                    _loguru_logger.debug("on_terminal_keypress: sortie")
                    return True
                elif cmd == _CONNECT:
                    self.on_btnConnect_clicked(None)
                elif cmd[0][0:8] == "console_":
                    page = int(cmd[0][8:]) - 1
                    widget.get_parent().get_parent().set_current_page(page)
                elif cmd == _NEW_LOCAL:
                    self.on_btnLocal_clicked(None)
                elif cmd == _ZOOM_IN:
                    self.terminal_zoom(widget, _TERMINAL_ZOOM_STEP)
                elif cmd == _ZOOM_OUT:
                    self.terminal_zoom(widget, -_TERMINAL_ZOOM_STEP)
                elif cmd == _ZOOM_RESET:
                    self.terminal_zoom(widget, reset=True)
            else:
                # comandos del usuario
                vte_feed(widget, cmd)

            _loguru_logger.debug("on_terminal_keypress: sortie")
            return True
        _loguru_logger.debug("on_terminal_keypress: sortie")
        return False

    def terminal_zoom(self, widget, delta=0, reset=False):
        """Ajuste la taille de police d'un terminal VTE (zoom Ctrl+/Ctrl-/Ctrl+0).

        Le zoom s'applique uniquement au terminal ayant recu l'evenement
        clavier (comportement par onglet, coherent avec les autres commandes
        de on_terminal_keypress comme _CLEAR/_COPY) : les autres onglets
        ouverts ne sont pas affectes. Le calcul de bornage pur est delegue a
        _compute_zoom_size() pour rester testable sans stub GTK/VTE.

        Args:
            widget (Vte.Terminal): Terminal cible.
            delta (float): Variation de taille en points (positive = zoom
                avant, negative = zoom arriere). Ignore si reset vaut True.
            reset (bool): Si True, revient a la taille configuree dans les
                preferences (conf.FONT) au lieu d'appliquer delta.
        """
        app_logger.debug(f"Wmain.terminal_zoom | delta={delta} reset={reset}")
        try:
            if reset:
                new_desc = Pango.FontDescription(conf.FONT or "monospace")
            else:
                current = widget.get_font()
                current = (
                    current.copy()
                    if current is not None
                    else Pango.FontDescription(conf.FONT or "monospace")
                )
                raw_size = current.get_size()
                size_pt = (raw_size / Pango.SCALE) if raw_size else _TERMINAL_ZOOM_DEFAULT_SIZE
                new_size_pt = _compute_zoom_size(size_pt, delta)
                new_size_units = int(round(new_size_pt * Pango.SCALE))
                if current.get_size_is_absolute():
                    current.set_absolute_size(new_size_units)
                else:
                    current.set_size(new_size_units)
                new_desc = current
            widget.set_font(new_desc)
            app_logger.debug(f"Wmain.terminal_zoom | police appliquee -> {new_desc.to_string()}")
        except Exception as e:
            app_logger.exception(f"Wmain.terminal_zoom | echec application du zoom : {e}")

    def on_terminal_selection(self, widget, *args):
        """Gestionnaire de changement de selection dans un terminal.

        Args:
            widget (Vte.Terminal): Terminal source.
            *args: Arguments supplementaires (ignorés).
        """
        _loguru_logger.debug("on_terminal_selection: entrée")
        if conf.AUTO_COPY_SELECTION:
            if widget.get_has_selection():
                self.terminal_copy(widget)
        _loguru_logger.debug("on_terminal_selection: sortie")
