    def find_word(self, backwards=False):
        """Recherche un mot dans le terminal actif.

        Args:
            backwards (bool): Si True, recherche dans la direction inverse (par défaut False).
        """
        _loguru_logger.debug("find_word: entrée")
        if not self.search:
            _loguru_logger.debug("find_word: sortie")
            return

        if self.search["pcre2"]:
            if backwards:
                self.search["terminal"].search_find_previous()
            else:
                self.search["terminal"].search_find_next()
            _loguru_logger.debug("find_word: sortie")
            return

        pos = -1
        if backwards:
            lst = list(range(0, self.search["index"]))
            lst.reverse()
            lst.extend(reversed(range(self.search["index"], len(self.search["lines"]))))
        else:
            lst = list(range(self.search["index"], len(self.search["lines"])))
            lst.extend(range(0, self.search["index"]))
        for i in lst:
            pos = self.search["lines"][i].find(self.search["word"])
            if pos != -1:
                self.search["index"] = i if backwards else i + 1
                # print('found at line %d column %d, index=%d, line: %s' %
                #   (i, pos, self.search['index'], self.search['lines'][i]))
                GLib.timeout_add(0, lambda: self.search["terminal"].get_vadjustment().set_value(i))
                # self.search['terminal'].get_vadjustment().set_value(i)
                self.search["terminal"].queue_draw()
                break
        if pos == -1:
            self.search["index"] = len(self.search["lines"]) if backwards else 0
        _loguru_logger.debug("find_word: fin")

    def init_search(self):
        """Initialise la barre de recherche dans le terminal."""
        _loguru_logger.debug("init_search: entrée")
        if (
            hasattr(self, "search")
            and self.search
            and self.get_widget("txtSearch").get_text() == self.search["word"]
            and self.current == self.search["terminal"]
        ):
            _loguru_logger.debug("init_search: sortie")
            return True

        terminal = self.find_active_terminal(self.hpMain)
        if terminal is None:
            terminal = self.current
        else:
            self.current = terminal
        if terminal is None:
            _loguru_logger.debug("init_search: sortie")
            return False

        self.search = {}
        text = self.get_widget("txtSearch").get_text()
        if text == "" or text == _("search..."):
            terminal.search_set_regex(None, 0)
            terminal.match_remove_all()
            _loguru_logger.debug("init_search: sortie")
            return True

        self.search["terminal"] = terminal
        self.search["word"] = text

        r = re.escape(text)
        try:
            new_reg = Vte.Regex.new_for_search(r, len(r), 0)
            new_reg_m = Vte.Regex.new_for_match(r, len(r), 0)
            terminal.search_set_regex(new_reg, 0)
            terminal.search_set_wrap_around(True)
            terminal.match_add_regex(new_reg_m, 0)
            self.search["pcre2"] = True
            _loguru_logger.debug("init_search: sortie")
            return True
        except Exception as e:
            app_logger.warning(f"PCRE2 indisponible ({e}), bascule sur recherche custom")
            self.search["pcre2"] = False
            # no hay soporte para pcre2, usar busqueda artesanal

        cols = terminal.get_column_count()
        lines, b = terminal.get_text_range(
            0, 0, terminal.get_property("scrollback-lines"), cols, None, None
        )
        wrapped = []
        for x in lines.splitlines():
            if len(x) == 0:
                wrapped.append(x)
            else:
                wrapped += self.chunkstring(x, cols)
        self.search["lines"] = wrapped
        self.search["index"] = len(self.search["lines"])
        _loguru_logger.debug("init_search: sortie")
        return True

    def chunkstring(self, string, length):
        """Decoupe une chaine en morceaux de taille fixe.

        Args:
            string (str): Chaine a decouper.
            length (int): Taille de chaque morceau.

        Returns:
            list[str]: Liste de sous-chaines.
        """
        return (string[0 + i : length + i] for i in range(0, len(string), length))

    def on_popupmenu(self, widget, item, *args):
        r"""Gestionnaire d\'action du menu contextuel.

        Args:
            widget (Gtk.Widget | None | widgets._LogActionShim): Widget
                source. ``None`` pour les items simples des menus d'onglet
                et de terminal portes vers Gio.Menu (voir
                ``widgets.TabContextMenu``, session-31, et
                ``widgets.PopupMenu``, session-33) qui n'ont plus de widget
                GTK individuel ; pour les items ``"L"``/``"L2"`` en
                provenance de ces memes menus, ``widgets._LogActionShim``
                (meme instance reutilisee pour les deux) reproduit
                l'interface ``get_active()``/``set_active()`` attendue
                ci-dessous sans modifier ce gestionnaire.
            item (str): Code d\'action du menu.
            *args: Arguments additionnels (ignorés).
        """
        _loguru_logger.debug("on_popupmenu: entrée")
        if item == "V":  # PASTE
            self.terminal_paste(self.popupMenu.terminal)
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "C":  # COPY
            self.terminal_copy(self.popupMenu.terminal)
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "CV":  # COPY and PASTE
            self.terminal_copy_paste(self.popupMenu.terminal)
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "A":  # SELECT ALL
            self.terminal_select_all(self.popupMenu.terminal)
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "CA":  # COPY ALL
            self.terminal_copy_all(self.popupMenu.terminal)
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "X":  # CLOSE CONSOLE
            widget = self.popupMenu.terminal.get_parent()
            notebook = widget.get_parent()
            page = notebook.page_num(widget)
            notebook.remove_page(page)
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "CP":  # CUSTOM COMMANDS
            vte_feed(self.popupMenu.terminal, args[0])
        elif item == "S":  # SAVE BUFFER
            self.show_save_buffer(self.popupMenu.terminal)
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "H":  # COPY HOST ADDRESS TO CLIPBOARD
            if self.treeServers.get_selection().get_selected()[
                1
            ] is not None and not self.treeModel.iter_has_child(
                self.treeServers.get_selection().get_selected()[1]
            ):
                host = self.treeModel.get_value(
                    self.treeServers.get_selection().get_selected()[1], 1
                )
                cb = Gtk.Clipboard.get_default(Gdk.Display.get_default())
                cb.set_text(host.host, len(host.host))
                cb.store()
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "D":  # DUPLICATE HOST
            if self.treeServers.get_selection().get_selected()[
                1
            ] is not None and not self.treeModel.iter_has_child(
                self.treeServers.get_selection().get_selected()[1]
            ):
                selected = self.treeServers.get_selection().get_selected()[1]
                group = self.get_group(selected)
                host = self.treeModel.get_value(selected, 1)
                newname = "%s (copy)" % (host.name)
                newhost = host.clone()
                for h in groups[group]:
                    if h.name == newname:
                        newname = "%s (copy)" % (newname)
                newhost.name = newname
                groups[group].append(newhost)
                self.updateTree()
                self.writeConfig()
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "R":  # RENAME TAB
            text = inputbox(
                _("Rename tab"),
                _("Enter new name"),
                self.popupMenuTab.label.get_text().strip(),
            )
            if text is not None and text != "":
                self.popupMenuTab.label.set_text("  %s  " % (text))
                nb = self.popupMenuTab.label.get_parent().get_parent().get_parent()
                nb.emit(
                    "switch-page",
                    nb.get_nth_page(nb.get_current_page()),
                    nb.get_current_page(),
                )
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "RS" or item == "RS2":  # RESET CONSOLE
            if item == "RS":
                tab = self.popupMenuTab.label.get_parent().get_parent()
                term = tab.widget_.get_children()[0]
            else:
                term = self.popupMenu.terminal
            term.reset(True, False)
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "RC" or item == "RC2":  # RESET AND CLEAR CONSOLE
            if item == "RC":
                tab = self.popupMenuTab.label.get_parent().get_parent()
                term = tab.widget_.get_children()[0]
            else:
                term = self.popupMenu.terminal
            term.reset(True, True)
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "RO":  # REOPEN SESION
            tab = self.popupMenuTab.label.get_parent().get_parent()
            term = tab.widget_.get_children()[0]
            if not hasattr(term, "command"):
                # term.fork_command(SHELL)
                vte_run(term, SHELL)
            else:
                # term.fork_command(term.command[0], term.command[1])
                vte_run(term, term.command[0], term.command[1])
                while Gtk.events_pending():
                    Gtk.main_iteration()

                # esperar 2 seg antes de enviar el pass para dar tiempo a que se levante
                # expect y prevenir que se muestre el pass
                if term.command[2] is not None and term.command[2] != "":
                    GLib.timeout_add(2000, self.send_data, term, term.command[2])
            tab.mark_tab_as_active()
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "CC" or item == "CC2":  # CLONE CONSOLE
            if item == "CC":
                tab = self.popupMenuTab.label.get_parent().get_parent()
                term = tab.widget_.get_children()[0]
                ntbk = tab.get_parent()
            else:
                term = self.popupMenu.terminal
                ntbk = term.get_parent().get_parent()
                tab = ntbk.get_tab_label(term.get_parent())
            if not hasattr(term, "host"):
                self.addTab(ntbk, tab.get_text())
            else:
                host = term.host.clone()
                host.name = tab.get_text()
                host.log = hasattr(term, "log_handler_id") and term.log_handler_id != 0
                self.addTab(ntbk, host)
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "L" or item == "L2":  # ENABLE/DISABLE LOG
            if item == "L":
                tab = self.popupMenuTab.label.get_parent().get_parent()
                term = tab.widget_.get_children()[0]
            else:
                term = self.popupMenu.terminal
            if conf.CONTINUOUS_TAB_LOG and not widget.get_active():
                msgbox(_("Continuous log mode is active and cannot be disabled per tab."))
                widget.set_active(True)
                _loguru_logger.debug("on_popupmenu: sortie")
                return True
            if not self.set_terminal_logger(term, widget.get_active()):
                widget.set_active(False)
            _loguru_logger.debug("on_popupmenu: sortie")
            return True
        elif item == "SPH":
            self.on_btnHSplit_clicked(widget, args)
        elif item == "SPV":
            self.on_btnVSplit_clicked(widget, args)
        elif item == "USP":
            self.on_btnUnsplit_clicked(widget, args)
        _loguru_logger.debug("on_popupmenu: fin")

    def createMenu(self):
        """Construit les menus contextuels de l'application.

        Cree trois menus, portes vers Gio.Menu (voir la note de session-33
        ci-dessous) :
        - popupMenu: menu contextuel du terminal (clic droit dans le
          terminal), porte vers Gio.Menu/Gio.SimpleActionGroup/Gtk.Popover
          depuis la session-33 (voir PopupMenu dans widgets.py) —
          troisieme et dernier des quatre menus contextuels applicatifs
          identifies par l'audit session-29
          (docs/gtk4-migration.md section 3.6-ter) a etre porte, sous-menu
          dynamique "Custom commands" inclus (section 3.6-sexies)
        - popupMenuFolder: menu contextuel du panneau de serveurs (clic
          droit sur host/groupe), porte vers Gio.Menu/Gio.SimpleActionGroup/
          Gtk.Popover depuis la session-32 (voir FolderContextMenu dans
          widgets.py) — deuxieme des quatre menus contextuels a etre porte
          (section 3.6-quinquies)
        - popupMenuTab: menu contextuel des onglets (clic droit sur un
          onglet), porte vers Gio.Menu/Gio.SimpleActionGroup/Gtk.Popover
          depuis la session-31 (voir TabContextMenu dans widgets.py) —
          premier des quatre menus contextuels a etre porte
          (section 3.6-quater)

        Les quatre menus contextuels applicatifs de l'audit session-29 sont
        desormais tous portes vers Gio.Menu. Reste hors perimetre de ce
        chantier (voir docs/gtk4-migration.md section 3.6-ter) : le
        constructeur generique RDP/VNC/SPICE de widgets.py
        (build_remote_desktop_context_menu(), 5eme ligne de l'inventaire
        d'origine), le declenchement Gtk.GestureClick (commun aux quatre) et
        le cas Gtk.Entry/populate-popup.
        """
        _loguru_logger.debug("createMenu: entrée")
        self.popupMenu = PopupMenu(self.on_popupmenu)
        self.popupMenu.populate_commands(select_command_shortcuts(shortcuts))

        # Menu contextual para panel de servidores — porte vers
        # Gio.Menu/Gtk.Popover (session-32, voir FolderContextMenu dans
        # widgets.py et docs/gtk4-migration.md section 3.6-quinquies).
        self.popupMenuFolder = FolderContextMenu(
            callbacks={
                "connect": lambda: self.on_btnConnect_clicked(None),
                "add": lambda: self.on_btnAdd_clicked(None),
                "new-group": lambda: self._on_new_group_clicked(None),
                "rename-group": lambda: self._on_rename_group_clicked(None),
                # Couleurs de groupe (features.md §4.2, "Couleurs par
                # groupe" — comme PuTTY) : une couleur posee sur un dossier
                # est heritee par ses sous-dossiers/hotes sans couleur
                # propre (gcm4_core.resolve_group_color()).
                "group-color": lambda: self._on_group_color_clicked(None),
                "group-color-reset": lambda: self._on_group_color_reset_clicked(None),
                "edit": lambda: self.on_bntEdit_clicked(None),
                "delete": lambda: self.on_btnDel_clicked(None),
                "expand": lambda: self.treeServers.expand_all(),
                "collapse": lambda: self.treeServers.collapse_all(),
            },
            dispatch=self.on_popupmenu,
        )
        # Items de menu contextuel specifiques a un protocole (ex: SSH
        # propose "Move to ssh_config…"/"Import from ssh_config…") : chaque
        # plugin declare les siens via build_folder_context_menu_items() --
        # aucun protocole n'est plus nomme ici, contrairement a avant.
        # Fournis via un provider evalue a chaque rebuild() (nombre et
        # libelles variables selon les plugins charges) plutot que par une
        # liste de Gtk.MenuItem construite une fois, cf. FolderContextMenu.
        self.popupMenuFolder.protocol_items_provider = lambda: [
            (label, callback)
            for plugin in self.plugin_registry.all_sorted()
            for label, callback in plugin.build_folder_context_menu_items()
        ]

        # Menu contextuel des onglets — porte vers Gio.Menu/Gtk.Popover
        # (session-31, voir TabContextMenu dans widgets.py et
        # docs/gtk4-migration.md section 3.6-ter). Premier des quatre menus
        # contextuels de createMenu() a etre porte ; popupMenu ci-dessus
        # reste en Gtk.Menu classique pour l'instant (sous-menu "Custom
        # commands" dynamique, cf. audit session-29).
        self.popupMenuTab = TabContextMenu(self.on_popupmenu)
        _loguru_logger.debug("createMenu: fin")

    def _build_primary_menu(self):
        """Construit le menu hamburger qui remplace l'ancien GtkMenuBar (palier 2).

        GTK4 supprime purement et simplement ``GtkMenuBar``/``GtkMenu``. En
        revanche ``Gio.Menu`` (GMenuModel) et ``Gio.SimpleAction`` existent
        depuis GTK 3.4 et sont directement réutilisables tels quels lors d'un
        futur port : un ``GtkPopoverMenu`` GTK4 se contente exactement du
        même modèle qu'un ``GtkMenuButton.set_menu_model()`` GTK3. C'est donc
        un rapprochement réel de GTK4, pas juste cosmétique — et ça élimine
        au passage toute duplication future entre un bouton et une entrée de
        menu, puisqu'une action n'est définie qu'une fois.

        Le sous-menu « Servers » (arbre des connexions dupliqué en ``Gtk.Menu``)
        a été supprimé : ``treeServers`` suffit à lui seul comme point d'entrée
        unique vers les connexions. « Custom commands » (cf.
        ``self.popupMenu.commands_model`` / ``PopupMenu.populate_commands()``,
        portés vers ``Gio.Menu`` en session-33 — voir
        ``docs/gtk4-migration.md`` section 3.6-sexies) est désormais lui aussi
        exposé via ``Gio.Menu``, mais reste ouvert en pop-up autonome à la
        demande (``PopupMenu.popup_commands_at()``, un clic de plus qu'avant,
        où il s'étendait en ligne dans le menu bar) plutôt que fusionné dans
        le modèle GMenu de ce menu hamburger : le modèle partagé est mutable
        et déjà maintenu à jour par ``createMenu()``/les Préférences, nul
        besoin de le dupliquer ici.
        """
        _loguru_logger.debug("_build_primary_menu: entrée")
        self._primary_actions = Gio.SimpleActionGroup()

        def add_action(name, handler):
            _loguru_logger.debug("Wmain.add_action: entrée")
            action = Gio.SimpleAction.new(name, None)
            action.connect("activate", lambda _a, _p: handler())
            self._primary_actions.add_action(action)
            _loguru_logger.debug("Wmain.add_action: sortie")
            return action

        def add_stateful_action(name, initial, on_change):
            _loguru_logger.debug("Wmain.add_stateful_action: entrée")
            action = Gio.SimpleAction.new_stateful(
                name, None, GLib.Variant.new_boolean(bool(initial))
            )

            def _on_change_state(a, value):
                _loguru_logger.debug("_on_change_state: entrée")
                on_change(value.get_boolean())
                a.set_state(value)
                _loguru_logger.debug("_on_change_state: fin")

            action.connect("change-state", _on_change_state)
            self._primary_actions.add_action(action)
            _loguru_logger.debug("Wmain.add_stateful_action: sortie")
            return action

        # -- File --
        add_action("save-buffer-as", lambda: self.on_guardar_como1_activate(None))
        add_action("import-servers", lambda: self.on_importar_servidores1_activate(None))
        add_action("export-servers", lambda: self.on_exportar_servidores1_activate(None))
        add_action("export-csv", lambda: self.on_mnu_export_csv_activate(None))
        add_action("export-json", lambda: self.on_mnu_export_json_activate(None))
        add_action("quit", lambda: self.on_salir1_activate(None))

        # -- Edit --
        add_action("copy", lambda: self.on_menuCopy_activate(None))
        add_action("paste", lambda: self.on_menuPaste_activate(None))
        add_action("copy-paste", lambda: self.on_menuCopyPaste_activate(None))
        add_action("select-all", lambda: self.on_menuSelectAll_activate(None))
        add_action("copy-all", lambda: self.on_menuCopyAll_activate(None))
        add_action(
            "custom-commands", lambda: self.popupMenu.popup_commands_at(self.btnPrimaryMenu)
        )
        add_action("settings", lambda: self.on_menuSettings_activate(None))

        # -- View (etat persistant, cf. set_panel_visible) --
        add_stateful_action("show-panel", conf.SHOW_PANEL, self.set_panel_visible)

        # -- Tools --
        add_action("cluster", lambda: self.on_btnCluster_clicked(None))
        add_action("open-workspace", lambda: self.on_open_workspace_clicked(None))

        # -- Help --
        add_action("about", lambda: self.on_acerca_de1_activate(None))

        # -- Actions de menu declarees par les plugins (cf. ConnectionPlugin.
        # menu_actions() dans plugin_base.py) : plus aucun protocole n'est
        # nomme ici. SSH y expose par exemple "Edit ~/.ssh/config…", "Move
        # all to ssh_config…", "Import from ssh_config…" et "Manage SSH
        # Keys…", regroupees ci-dessous dans une section dediee du menu
        # "Edit" (cf. protocol_menu_items).
        protocol_menu_items: list[tuple[str, str]] = []
        for plugin in self.plugin_registry.all_sorted():
            for action_name, label, callback in plugin.menu_actions():
                add_action(action_name, callback)
                protocol_menu_items.append((label, action_name))

        # -- Outils charges dynamiquement (BatchPlugin, cf. plugin_base.py) --
        # Une seule action par plugin, quelle que soit sa section de menu
        # (evite tout double-enregistrement si un futur menu_section
        # additionnel referencait le meme plugin). Repartis ensuite dans le
        # sous-menu "Imports" ("import") ou la section "Outils" ("tools",
        # defaut) au moment de construire chaque section, ci-dessous. Aucun
        # outil non fonctionnel n'apparait : si un plugin attendu a echoue
        # au chargement, _warn_if_batch_plugin_failed() (deja appelee dans
        # __init__) previent l'utilisateur separement.
        batch_plugins_by_section: dict[str, list] = {}
        for batch_plugin in self.batch_plugin_registry.all():
            action_name = f"batch-{batch_plugin.tool_id}"
            add_action(action_name, self._make_batch_plugin_activator(batch_plugin))
            batch_plugins_by_section.setdefault(batch_plugin.menu_section, []).append(
                (batch_plugin.display_name, action_name)
            )

        self.window.insert_action_group("win", self._primary_actions)

        menu = Gio.Menu()

        file_section1 = Gio.Menu()
        file_section1.append(_("Save buffer as"), "win.save-buffer-as")

        # Sous-menu "Imports" : le format natif GCM (statique) suivi de
        # chaque BatchPlugin d'import charge dynamiquement — CSV, JSON,
        # libvirt, Proxmox, VirtualBox, oVirt... Ajouter un hyperviseur ou
        # un format ne touche plus a ce fichier : cf. les plugin_import_*.py.
        imports_submenu = Gio.Menu()
        imports_submenu.append(_("Import servers"), "win.import-servers")
        for display_name, action_name in batch_plugins_by_section.get("import", []):
            imports_submenu.append(display_name, f"win.{action_name}")
        file_section1.append_submenu(_("Imports"), imports_submenu)

        # Sous-menu "Exports" : uniquement le format natif GCM et CSV/JSON
        # (pas de BatchPlugin d'export pour l'instant — cf. discussion sur
        # le pourquoi de cette asymetrie avec "Imports").
        exports_submenu = Gio.Menu()
        exports_submenu.append(_("Export servers"), "win.export-servers")
        exports_submenu.append(_("Export to CSV…"), "win.export-csv")
        exports_submenu.append(_("Export to JSON…"), "win.export-json")
        file_section1.append_submenu(_("Exports"), exports_submenu)

        file_section3 = Gio.Menu()
        file_section3.append(_("Quit"), "win.quit")
        file_menu = Gio.Menu()
        file_menu.append_section(None, file_section1)
        file_menu.append_section(None, file_section3)
        menu.append_submenu(_("File"), file_menu)

        edit_section1 = Gio.Menu()
        edit_section1.append(_("Copy"), "win.copy")
        edit_section1.append(_("Paste"), "win.paste")
        edit_section1.append(_("Copy and Paste"), "win.copy-paste")
        edit_section1.append(_("Select all"), "win.select-all")
        edit_section1.append(_("Copy all"), "win.copy-all")
        edit_section2 = Gio.Menu()
        edit_section2.append(_("Custom commands…"), "win.custom-commands")
        edit_section3 = Gio.Menu()
        for label, action_name in protocol_menu_items:
            edit_section3.append(label, f"win.{action_name}")
        edit_section4 = Gio.Menu()
        edit_section4.append(_("Settings"), "win.settings")
        edit_menu = Gio.Menu()
        edit_menu.append_section(None, edit_section1)
        edit_menu.append_section(None, edit_section2)
        edit_menu.append_section(None, edit_section3)
        edit_menu.append_section(None, edit_section4)
        menu.append_submenu(_("Edit"), edit_menu)

        view_menu = Gio.Menu()
        view_menu.append(_("Show Panel"), "win.show-panel")
        menu.append_submenu(_("View"), view_menu)

        tools_section = Gio.Menu()
        tools_section.append(_("Cluster…"), "win.cluster")
        tools_section.append(_("Open Workspace"), "win.open-workspace")
        for display_name, action_name in batch_plugins_by_section.get("tools", []):
            tools_section.append(display_name, f"win.{action_name}")
        menu.append_section(None, tools_section)

        help_menu = Gio.Menu()
        help_menu.append(_("About"), "win.about")
        menu.append_submenu(_("Help"), help_menu)

        self.btnPrimaryMenu = self.get_widget("btnPrimaryMenu")
        self.btnPrimaryMenu.set_menu_model(menu)
        _loguru_logger.debug("_build_primary_menu: fin")

    def _open_connection_tab(self, notebook, host):
        """Ouvre un onglet de connexion pour ``host.protocol``, quel qu'il soit.

        Point d'entree GENERIQUE unique : le comportement (terminal VTE
        cable avec ses signaux, ou widget autonome eventuellement enveloppe
        dans un ``Gtk.ScrolledWindow``) est entierement pilote par les
        attributs que le plugin annonce lui-meme (``is_terminal`` /
        ``self_scrolling``, cf. ``plugin_base.ConnectionPlugin``) — ce coeur
        d'application ne connait plus aucun protocole precis : il decouvre
        tout depuis le plugin enregistre sous ``host.protocol``.

        Args:
            notebook (Gtk.Notebook): Notebook cible.
            host (Host): Hote a connecter (``host.protocol`` determine le
                plugin utilise).

        Returns:
            Gtk.Widget: Widget (ou son conteneur) ajoute au notebook.
        """
        _loguru_logger.debug("_open_connection_tab: entrée")
        proto = getattr(host, "protocol", "ssh") or "ssh"
        plugin = self.plugin_registry.get(proto)
        if plugin is None:
            raise ValueError(f"Protocole inconnu ou plugin non charge : {proto!r}")

        run_pre_connect_hook(host)

        def get_pwd():
            _loguru_logger.debug("Wmain.get_pwd: entrée")
            try:
                app_logger.debug(
                    f"Password requested for host {host.name} (provided={bool(host.password)})"
                )
                _loguru_logger.debug("Wmain.get_pwd: sortie")
                return host.password
            except Exception as e:
                app_logger.debug(f"Failed to decrypt password for host {host.name}: {e}")
                _loguru_logger.debug("Wmain.get_pwd: sortie")
                return ""
            _loguru_logger.debug("Wmain.get_pwd: fin")

        widget = plugin.build_tab(host, get_pwd)
        connect = getattr(widget, f"connect_{proto}", None)
        post_connect_command = resolve_post_connect_command(host, proto)

        if plugin.is_terminal:
            v = widget.terminal
            tab = NotebookTabLabel(
                " %s " % host.name,
                notebook,
                widget,
                self.popupMenuTab,
                getattr(host, "auto_close_tab", ""),
                post_connect_command,
            )

            v.connect("child-exited", self._on_terminal_child_exited, tab)
            v.connect("focus", self.on_tab_focus)
            self.attach_terminal_click_gesture(v)
            v.connect("key_press_event", self.on_terminal_keypress)
            v.connect("selection-changed", self.on_terminal_selection)

            widget.show_all()
            notebook.append_page(widget, tab_label=tab)
            notebook.set_current_page(notebook.page_num(widget))
            notebook.set_tab_reorderable(widget, True)
            notebook.set_tab_detachable(widget, True)
            self.wMain.set_focus(v)
            self.on_tab_focus(v)
            self.set_terminal_logger(v, host.log or conf.CONTINUOUS_TAB_LOG)

            GLib.timeout_add(200, lambda: self.wMain.set_focus(v))

            while Gtk.events_pending():
                Gtk.main_iteration()

            if connect is not None:
                connect()
            _loguru_logger.debug("_open_connection_tab: sortie")
            return widget

        if plugin.self_scrolling:
            target = widget
        else:
            target = Gtk.ScrolledWindow()
            target.set_policy(Gtk.PolicyType.AUTOMATIC, Gtk.PolicyType.AUTOMATIC)
            target.add(widget)

        target.show_all()
        tab_label = NotebookTabLabel(
            " %s " % host.name,
            notebook,
            target,
            self.popupMenuTab,
            getattr(host, "auto_close_tab", ""),
            post_connect_command,
        )
        notebook.append_page(target, tab_label)
        notebook.set_tab_reorderable(target, True)
        notebook.set_current_page(notebook.get_n_pages() - 1)
        if connect is not None:
            connect()
        _loguru_logger.debug("_open_connection_tab: sortie")
        return target

    def _import_done(self, host_dicts, default_group="IMPORT"):
        """Ajoute des hôtes importés dans le groupe fixe (pas de sous-groupe via nom VM).

        Args:
            host_dicts (list[dict]): Connexions importées.
            default_group (str): Nom de groupe cible (LIBVIRT, PROXMOX…).

        Returns:
            int: Nombre d'hôtes ajoutés.
        """
        _loguru_logger.debug("_import_done: entrée")
        added = 0
        for d in host_dicts:
            # Ignorer la ventilation par nom — tout va dans default_group
            gname = default_group
            if gname not in groups:
                groups[gname] = []
            if d["name"] in [h.name for h in groups[gname]]:
                continue

            proto = d.get("protocol", d.get("type", "ssh"))
            kwargs = {
                "group": gname,
                "name": d["name"],
                "host": d.get("host", ""),
                "user": d.get("user", "root"),
                "password": "",
                "private_key": "",
                "description": d.get("description", ""),
                "log": False,
                "tunnel": "",
                "type": d.get("type", proto),
                "commands": "",
                "keep_alive": 0,
                "font_color": "",
                "back_color": "",
                "x11": False,
                "agent": True,
                "compression": False,
                "compressionLevel": "",
                "extra_params": d.get("extra_params", ""),
                "backspace_key": 0,
                "delete_key": 0,
                "term": "",
                "protocol": proto,
                "port": str(d.get("port", 22)),
            }
            # Champs protocole-spécifiques : valeur fournie par l'import sinon
            # défaut déclaré par le plugin — aucun nom de champ codé en dur ici.
            for field_name, default in self.plugin_registry.all_host_fields():
                kwargs[field_name] = d.get(field_name, default)
            # rdp_cert_ignore : défaut à True seulement si le protocole importé est RDP
            if "rdp_cert_ignore" in kwargs:
                kwargs["rdp_cert_ignore"] = d.get("rdp_cert_ignore", proto == "rdp")

            h = Host(**kwargs)

            # ── SPICE : décoder extra_params legacy → attributs structurés ────
            # Logique de migration spécifique à l'ancien format d'export SPICE
            # (libvirt/proxmox) — décodage légitimement protocole-spécifique,
            # appliqué en override après construction générique du Host.
            _ep = (d.get("extra_params") or "").strip()
            if proto == "spice" and _ep.startswith("--connect "):
                # format libvirt : "--connect qemu+ssh://user@host[:port]/system vm_name"
                _parts = _ep.split(None, 2)
                h.spice_mode = "libvirt"
                h.spice_libvirt_uri = _parts[1] if len(_parts) > 1 else ""
                h.spice_vm_name = _parts[2] if len(_parts) > 2 else ""
                h.spice_tls_port = ""
                h.spice_ca_cert = ""
                h.spice_px_node = ""
                h.spice_px_vmid = ""
                # Vider extra_params : les infos sont maintenant dans les attributs
                h.extra_params = ""
            elif proto == "spice" and _ep.startswith("--proxmox "):
                # format proxmox legacy : "--proxmox NODE VMID"
                _parts = _ep.split()
                h.spice_mode = "proxmox"
                h.spice_px_node = _parts[1] if len(_parts) > 1 else ""
                h.spice_px_vmid = _parts[2] if len(_parts) > 2 else ""
                h.spice_libvirt_uri = ""
                h.spice_vm_name = ""
                h.spice_tls_port = ""
                h.spice_ca_cert = ""
                h.extra_params = ""

            groups[gname].append(h)
            added += 1
        self.updateTree()
        self.writeConfig()
        _loguru_logger.debug("_import_done: sortie")
        return added

    # ── CSV / JSON import/export ──────────────────────────────────────────────

    #: Champs "core" exportés (sans mot de passe), communs à tous les protocoles.
    _CSV_CORE_FIELDS = [
        "group",
        "name",
        "description",
        "host",
        "user",
        "port",
        "type",
        "protocol",
        "extra_params",
        "commands",
        "keep_alive",
        "font_color",
        "back_color",
        "x11",
        "agent",
        "compression",
        "compressionLevel",
        "log",
        "backspace_key",
        "delete_key",
        "term",
    ]

    def _csv_fields(self):
        """Retourne la liste complète des champs exportés en CSV/JSON.

        Champs core (ci-dessus) + tous les champs protocole-spécifiques
        appris dynamiquement des plugins enregistrés — aucun nom de
        protocole ni de champ n'est codé en dur ici.

        Returns:
            list[str]: Noms de champs, core puis protocole-spécifiques.
        """
        return self._CSV_CORE_FIELDS + [
            name for name, _default in self.plugin_registry.all_host_fields()
        ]

    def _all_hosts(self):
        """Retourne la liste plate de tous les Host."""
        return [h for grp in groups.values() for h in grp]

    def _host_to_dict(self, h):
        """Sérialise un Host en dict sans mot de passe."""
        return {f: str(getattr(h, f, "") or "") for f in self._csv_fields()}

    @staticmethod
    def _coerce_field_value(default, raw):
        """Convertit une valeur brute (texte issu d'un CSV/JSON) vers le type de default.

        Utilisé par ``_dict_to_host`` pour tous les champs — core ET
        protocole-spécifiques — sans jamais connaître leurs noms : seul le
        type de la valeur par défaut (déclarée par ``_CORE_FIELDS`` ou par
        ``ConnectionPlugin.host_fields()``) détermine la conversion.

        Args:
            default: Valeur par défaut du champ (détermine le type cible).
            raw: Valeur brute lue dans le dict importé.

        Returns:
            Valeur convertie (bool/int/str selon le type de default).
        """
        _loguru_logger.debug("_coerce_field_value: entrée")
        if raw is None:
            _loguru_logger.debug("_coerce_field_value: sortie")
            return default
        if isinstance(default, bool):
            _loguru_logger.debug("_coerce_field_value: sortie")
            return str(raw).strip().lower() in ("true", "1", "yes")
        if isinstance(default, int):
            try:
                _loguru_logger.debug("_coerce_field_value: sortie")
                return int(raw)
            except (TypeError, ValueError) as exc:
                _loguru_logger.debug("préférence {!r} non entière, défaut : {}", raw, exc)
                _loguru_logger.debug("_coerce_field_value: sortie")
                return default
        _loguru_logger.debug("_coerce_field_value: sortie")
        return raw

    def _dict_to_host(self, d):
        """Désérialise un dict en Host (pas de mot de passe).

        Champs core codés en dur (universels) + champs protocole-spécifiques
        appris dynamiquement de ``plugin_registry.all_host_fields()`` — ajouter
        un protocole avec ses propres champs ne nécessite aucune modification
        de cette méthode.
        """
        _loguru_logger.debug("_dict_to_host: entrée")
        kwargs = {
            "group": d.get("group", "IMPORT"),
            "name": d.get("name", ""),
            "description": d.get("description", ""),
            "host": d.get("host", ""),
            "user": d.get("user", ""),
            "password": "",
            "private_key": "",
            "port": d.get("port", "22"),
            "tunnel": "",
            "type": d.get("type", "ssh"),
            "commands": d.get("commands", ""),
            "keep_alive": self._coerce_field_value(0, d.get("keep_alive")),
            "font_color": d.get("font_color", ""),
            "back_color": d.get("back_color", ""),
            "x11": self._coerce_field_value(False, d.get("x11")),
            "agent": self._coerce_field_value(False, d.get("agent")),
            "compression": self._coerce_field_value(False, d.get("compression")),
            "compressionLevel": d.get("compressionLevel", ""),
            "extra_params": d.get("extra_params", ""),
            "log": self._coerce_field_value(False, d.get("log")),
            "backspace_key": self._coerce_field_value(0, d.get("backspace_key")),
            "delete_key": self._coerce_field_value(0, d.get("delete_key")),
            "term": d.get("term", ""),
            "protocol": d.get("protocol", d.get("type", "ssh")),
        }
        for field_name, default in self.plugin_registry.all_host_fields():
            kwargs[field_name] = self._coerce_field_value(default, d.get(field_name))
        _loguru_logger.debug("_dict_to_host: sortie")
        return Host(**kwargs)

    def _import_hosts_from_list(self, host_list):
        """Ajoute une liste de Host dans le modèle et écrit la config."""
        _loguru_logger.debug("_import_hosts_from_list: entrée")
        added = 0
        for h in host_list:
            gname = h.group or "IMPORT"
            if gname not in groups:
                groups[gname] = []
            # Skip doublons (même nom dans même groupe)
            if any(x.name == h.name for x in groups[gname]):
                continue
            groups[gname].append(h)
            added += 1
        self.updateTree()
        self.writeConfig()
        _loguru_logger.debug("_import_hosts_from_list: sortie")
        return added

    def on_mnu_export_csv_activate(self, widget, *args):
        """Exporte toutes les connexions vers un fichier CSV (sans mot de passe)."""
        _loguru_logger.debug("on_mnu_export_csv_activate: entrée")
        filename = show_open_dialog(
            parent=self.wMain, title=_("Export to CSV"), action=Gtk.FileChooserAction.SAVE
        )
        if not filename:
            _loguru_logger.debug("on_mnu_export_csv_activate: sortie")
            return
        if not filename.endswith(".csv"):
            filename += ".csv"
        import csv as _csv

        try:
            hosts = self._all_hosts()
            with open(filename, "w", newline="", encoding="utf-8") as f:
                writer = _csv.DictWriter(f, fieldnames=self._csv_fields())
                writer.writeheader()
                for h in hosts:
                    writer.writerow(self._host_to_dict(h))
        except Exception as e:
            _loguru_logger.error("export CSV impossible : {}", e)
            msgbox(_("CSV export error: {e}").format(e=e))
            _loguru_logger.debug("on_mnu_export_csv_activate: sortie")
            return
        msgbox(
            _("{count} connection(s) exported to {filename}.").format(
                count=len(hosts), filename=filename
            )
        )
        _loguru_logger.debug("on_mnu_export_csv_activate: fin")

    def on_mnu_export_json_activate(self, widget, *args):
        """Exporte toutes les connexions vers un fichier JSON (sans mot de passe)."""
        _loguru_logger.debug("on_mnu_export_json_activate: entrée")
        filename = show_open_dialog(
            parent=self.wMain, title=_("Export to JSON"), action=Gtk.FileChooserAction.SAVE
        )
        if not filename:
            _loguru_logger.debug("on_mnu_export_json_activate: sortie")
            return
        if not filename.endswith(".json"):
            filename += ".json"
        import json as _json

        try:
            hosts = self._all_hosts()
            data = [self._host_to_dict(h) for h in hosts]
            with open(filename, "w", encoding="utf-8") as f:
                _json.dump(data, f, indent=2, ensure_ascii=False)
        except Exception as e:
            _loguru_logger.error("export JSON impossible : {}", e)
            msgbox(_("JSON export error: {e}").format(e=e))
            _loguru_logger.debug("on_mnu_export_json_activate: sortie")
            return
        msgbox(
            _("{count} connection(s) exported to {filename}.").format(
                count=len(hosts), filename=filename
            )
        )
        _loguru_logger.debug("on_mnu_export_json_activate: fin")

