    def on_btnUnsplit_clicked(self, widget, *args):
        """Gestionnaire du bouton Annuler la division.

        Args:
            widget (Gtk.Button): Bouton clique.
            *args: Arguments supplémentaires.
        """
        _loguru_logger.debug("on_btnUnsplit_clicked: entrée")
        wid = self.find_notebook(self.hpMain, self.nbConsole)
        while wid is not None:
            # Mover los tabs al notebook principal
            while wid.get_n_pages() != 0:
                csp = wid.get_nth_page(0)
                old_tab_label = wid.get_tab_label(csp)
                text = old_tab_label.get_text()
                # Idem split_notebook() : reporter la surcharge par hôte de
                # l'onglet d'origine (et sa commande "après connexion" déjà
                # résolue), pas de Host disponible ici (annulation de
                # division, simple déplacement de widget).
                host_auto_close_tab = getattr(old_tab_label, "host_auto_close_tab", "")
                host_post_connect_command = getattr(
                    old_tab_label, "host_post_connect_command", None
                )
                csp.get_parent().remove(csp)
                self.nbConsole.add(csp)
                csp = self.nbConsole.get_nth_page(self.nbConsole.get_n_pages() - 1)
                tab = NotebookTabLabel(
                    text,
                    self.nbConsole,
                    csp,
                    self.popupMenuTab,
                    host_auto_close_tab,
                    host_post_connect_command,
                )
                self.nbConsole.set_tab_label(csp, tab_label=tab)
                self.nbConsole.set_tab_reorderable(csp, True)
                self.nbConsole.set_tab_detachable(csp, True)
            wid = self.find_notebook(self.hpMain, self.nbConsole)
        self.on_tab_focus(
            self.nbConsole,
            self.nbConsole.get_nth_page(self.nbConsole.get_current_page()),
        )
        _loguru_logger.debug("on_btnUnsplit_clicked: fin")

