    def on_btnSearch_key_press(self, widget, event, *args):
        """Gestionnaire de touche dans la zone de recherche.

        Args:
            widget (Gtk.Entry): Champ de saisie.
            event (Gdk.EventKey): Evenement clavier.
            *args: Arguments supplémentaires.
        """
        _loguru_logger.debug("on_btnSearch_key_press: entrée")
        if event.state & (Gdk.ModifierType.SHIFT_MASK | Gdk.ModifierType.CONTROL_MASK):
            _loguru_logger.debug("on_btnSearch_key_press: sortie")
            return
        if event.keyval in (Gdk.KEY_Return, Gdk.KEY_KP_Enter):
            if self.init_search():
                self.find_word()
        elif event.keyval == Gdk.KEY_Escape:
            widget.set_text("")
            self.init_search()
            self.get_widget("searchBar").hide()
        _loguru_logger.debug("on_btnSearch_key_press: fin")

    # -- Wmain.on_btnCluster_clicked {
    # -- Wmain._make_batch_plugin_activator {
    def _make_batch_plugin_activator(self, batch_plugin):
        """Retourne le callback d'action de menu pour un ``BatchPlugin``.

        Un seul chemin generique pour TOUS les outils "Outils" du menu
        (cf. ``_build_primary_menu``), quel que soit le plugin — plus
        besoin d'un ``on_mnu_xxx_activate`` par outil. Toute exception levee
        par ``activate()`` est capturee ici : journalisee avec sa cause
        precise, et signalee a l'utilisateur via une boite de dialogue
        plutot que de remonter comme un plantage silencieux.
        """

        _loguru_logger.debug("_make_batch_plugin_activator: entrée")

        def _activate():
            _loguru_logger.debug("Wmain._activate: entrée")
            try:
                batch_plugin.activate()
            except Exception as exc:  # noqa: BLE001
                app_logger.exception(
                    f"BatchPlugin '{batch_plugin.tool_id}' | echec activate() : {exc}"
                )
                msgbox(
                    _(
                        "L'outil « {name} » n'a pas pu s'ouvrir.\n\n"
                        "Cause : {error}\n\n"
                        "Détails complets dans le journal de l'application."
                    ).format(name=batch_plugin.display_name, error=exc),
                    parent=self.window,
                )
            _loguru_logger.debug("Wmain._activate: fin")

        _loguru_logger.debug("_make_batch_plugin_activator: sortie")
        return _activate

    # -- Wmain._make_batch_plugin_activator }

    # -- Wmain._warn_if_batch_plugin_failed {
    def _warn_if_batch_plugin_failed(self):
        """Avertit visiblement l'utilisateur si un outil (BatchPlugin) n'a
        pas pu se charger au demarrage — ex. ``plugin_netmiko_push.py``.

        ``BatchPluginRegistry.autoload()`` journalise deja chaque echec en
        warning avec sa cause (cf. ``plugin_base.py``), mais un warning dans
        le journal ne suffit pas a etre vu : cette methode relaie
        ``self.batch_plugin_registry.load_errors`` dans une boite de
        dialogue, une seule fois au demarrage. Un module ``plugin_*.py`` qui
        appartient a l'autre famille (``ConnectionPlugin``) n'y figure
        jamais — seuls les VRAIS echecs sont remontes (cf.
        ``BatchPluginRegistry.autoload``).
        """
        _loguru_logger.debug("_warn_if_batch_plugin_failed: entrée")
        errors = self.batch_plugin_registry.load_errors
        if not errors:
            _loguru_logger.debug("_warn_if_batch_plugin_failed: sortie")
            return

        lines = [f"• {module} : {cause}" for module, cause in errors.items()]
        message = _(
            "{n} outil(s) n'ont pas pu se charger au démarrage :\n\n{details}\n\n"
            "L'application continue de fonctionner normalement sans eux. "
            "Détails complets dans le journal de l'application."
        ).format(n=len(errors), details="\n".join(lines))

        # Différé après la boucle principale : self.window est déjà créée
        # (cf. __init__) mais peut ne pas être encore affichée à cet
        # instant précis de la construction de Wmain.
        GLib.idle_add(lambda: (msgbox(message, parent=self.window), False)[1])
        _loguru_logger.debug("_warn_if_batch_plugin_failed: fin")

    # -- Wmain._warn_if_batch_plugin_failed }

    def on_btnCluster_clicked(self, widget, *args):
        """Gestionnaire du bouton Cluster.

        Args:
            widget (Gtk.Button): Bouton clique.
            *args: Arguments supplémentaires.
        """
        # obtenir la liste des consoles ouvertes
        _loguru_logger.debug("on_btnCluster_clicked: entrée")
        consoles = []
        obj = wMain.hpMain
        s = []
        s.append(obj)
        while len(s) > 0:
            obj = s.pop()
            # agregar hijos de p a s
            if hasattr(obj, "get_children"):
                for w in obj.get_children():
                    if isinstance(w, Gtk.Notebook) or hasattr(w, "get_children"):
                        s.append(w)

            if isinstance(obj, Gtk.Notebook):
                n = obj.get_n_pages()
                for i in range(0, n):
                    terminal = obj.get_nth_page(i).get_children()[0]
                    title = obj.get_tab_label(obj.get_nth_page(i)).get_text()
                    consoles.append((title, terminal))

        if len(consoles) == 0:
            msgbox(_("No open consoles"))
            _loguru_logger.debug("on_btnCluster_clicked: sortie")
            return True

        def _factory(consoles=consoles):
            return Wcluster(terms=consoles, show=False)

        self.open_management_tab("cluster", _("Cluster"), _factory)
        _loguru_logger.debug("on_btnCluster_clicked: sortie")
        return True

