    def get_widget(self, name):
        """Retrouve un widget par son id .glade d'origine.

        Equivalent, pour Whost, de ce que faisait Gtk.Builder.get_object
        via GCMBase._normalize_names : chaque widget nomme du .glade est
        pose comme attribut direct ``self.<id>`` au moment de sa
        construction dans __init__ ; cette methode fait juste le lien pour
        tous les appels ``self.get_widget("...")`` deja presents dans le
        reste de l'enorme classe (chargement/sauvegarde d'un hote,
        plugins...), non modifies par la conversion.

        Args:
            name (str): Id .glade d'origine du widget recherche.

        Returns:
            Gtk.Widget | None: Le widget correspondant, ou None si absent.
        """
        return getattr(self, name, None)

    # -- Whost.new {
    def new(self):
        """Cree et retourne une nouvelle instance depuis le fichier Glade.

        Returns:
            instance: Nouvelle instance de la classe.
        """

        _loguru_logger.debug("new: entrée")
        self.cmbGroup = self.get_widget("cmbGroup")
        # Le groupe est géré via l'arborescence — lecture seule dans le dialogue
        # On stocke la valeur dans un attribut dédié pour la récupérer à la validation
        self._group_value = ""
        self.cmbGroup.set_sensitive(False)
        if self.cmbGroup.get_has_entry() and self.cmbGroup.get_child():
            self.cmbGroup.get_child().set_editable(False)
        # Bouton OK vert, comme Save/Connect/Use ailleurs dans l'application
        self.okbutton_host.get_style_context().add_class("suggested-action")
        self.txtName = self.get_widget("txtName")
        self.txtDescription = self.get_widget("txtDescription")
        self.txtHost = self.get_widget("txtHost")
        self.cmbType = self.get_widget("cmbType")
        self.txtUser = self.get_widget("txtUser")
        self.txtPass = self.get_widget("txtPassword")
        self.txtPrivateKey = self.get_widget("txtPrivateKey")
        self.btnBrowse = self.get_widget("btnBrowse")
        self.txtPort = self.get_widget("txtPort")
        # Done programaticaly because engine does not see top-level abjustment object
        txtPortAdjustment = Gtk.Adjustment(
            value=22, lower=1, upper=65535, step_increment=1, page_increment=10
        )
        self.txtPort.set_adjustment(txtPortAdjustment)
        self.cmbGroup.remove_all()
        for group in groups:
            self.cmbGroup.append_text(group)
        self.isNew = True

        self.txtComamnds = self.get_widget("txtCommands")
        self.chkComamnds = self.get_widget("chkCommands")
        buf = self.txtComamnds.get_buffer()
        buf.create_tag("DELAY1", style=Pango.Style.ITALIC, foreground="darkgray")
        buf.create_tag("DELAY2", style=Pango.Style.ITALIC, foreground="cadetblue")
        buf.connect("changed", self.update_texttags)
        self.btnFColor = self.get_widget("btnFColor")
        self.btnBColor = self.get_widget("btnBColor")
        self.chkLogging = self.get_widget("chkLogging")
        self.cmbBackspace = self.get_widget("cmbBackspace")
        self.cmbDelete = self.get_widget("cmbDelete")
        self.txtTerm = self.get_widget("txtTerm")
        self.cmbBackspace.set_active(0)
        self.cmbDelete.set_active(0)

        # cmbProtocol = alias vers cmbType (le widget glade affiché à l'utilisateur)
        self.cmbProtocol = self.cmbType

        # ── Onglets dedies aux plugins (RDP/VNC/SPICE/Web/SSH/Serial) ───────
        # Chaque plugin s'enregistre toujours (aucun protocole n'est nomme
        # en dur ici) : sa page remplace le placeholder pose en __init__
        # (meme position dans nbHost), au fil de self._PLUGIN_TAB_ATTRS.
        self._plugin_page = {}
        for proto, attr_name in self._PLUGIN_TAB_ATTRS.items():
            plugin = wMain.plugin_registry.get(proto)
            placeholder = getattr(self, attr_name)
            page = plugin.build_edit_page()
            pos = self.nbHost.page_num(placeholder)
            if pos != -1:
                self.nbHost.remove_page(pos)
            self.nbHost.insert_page(page, Gtk.Label(label=plugin.display_name), pos)
            setattr(self, attr_name, page)
            page.show()
            self._plugin_page[proto] = page

        # Widgets Properties nécessaires au masquage dynamique par protocole
        self.lblHost = self.get_widget("lblHost")
        self.lblPort = self.get_widget("lblPort")
        self.lblUser = self.get_widget("lblUser")
        self.lblPassword = self.get_widget("lblPassword")
        self.lblPrivateKey = self.get_widget("lblPrivateKey")
        self.gridPrivateKeyRow = self.get_widget("gridPrivateKeyRow")
        self.lblLogging = self.get_widget("lblLogging")
        self.lblTerm = self.get_widget("lblTerm")

        # Reaffirme l'ordre et les libelles des pages de nbHost (voir
        # docstring de _fix_host_notebook_pages : depuis la construction
        # Python pure de Whost, ce n'est plus un contournement necessaire,
        # juste un filet de securite inoffensif conserve par prudence).
        self._fix_host_notebook_pages()

        # cmbType.set_active() est déclenché seulement maintenant : le
        # signal "changed" appelle on_cmbType_changed -> _update_host_tabs_for_type,
        # qui a besoin de self._plugin_page (construit juste au-dessus).
        # L'appeler plus tot (avant la boucle de construction des pages)
        # provoque : AttributeError: 'Whost' object has no attribute '_plugin_page'.
        self.cmbType.set_active(0)

        # Affichage dynamique des onglets selon le type de connexion
        # (ex: SSH -> Advanced SSH / Port forwarding / SSHFS visibles,
        # RDP -> uniquement l'onglet RDP, etc.)
        self._update_host_tabs_for_type(self.cmbType.get_active_id() or "ssh")
        _loguru_logger.debug("new: fin")

