    # Association protocole -> attribut de placeholder/page dans nbHost,
    # pour chaque plugin ayant un onglet d'edition dedie (utilise en __init__
    # et dans new() : aucun protocole n'est plus nomme en dur ailleurs).
    _PLUGIN_TAB_ATTRS = {
        "rdp": "pgHostRdp",
        "vnc": "pgHostVnc",
        "spice": "pgHostSpice",
        "serial": "pgHostSerial",
        "web": "pgHostWeb",
        "ssh": "pgHostSsh",
    }

    # Ordre canonique des pages du notebook Edit Host, par id glade stable,
    # avec le libelle a afficher pour chacune.
    _HOST_NOTEBOOK_PAGES = [
        ("swHostProps", "General"),
        ("swHostCommands", "Commands"),
        ("swHostColorsKeys", "Colors and Keys"),
        ("pgHostSsh", "SSH"),
        ("pgHostRdp", "RDP"),
        ("pgHostVnc", "VNC"),
        ("pgHostSpice", "SPICE"),
        ("pgHostSerial", "Serial"),
        ("pgHostWeb", "Web"),
    ]

    def _fix_host_notebook_pages(self):
        """Reimpose l'ordre et les libelles des pages du notebook Edit Host.

        Historiquement, contournement d'un comportement de GtkBuilder :
        quand le .glade etait charge partiellement via
        add_objects_from_file(), les pages du notebook nbHost pouvaient se
        retrouver dans un ordre different de celui de leurs libelles
        d'onglet, et/ou le libelle affiche pouvait retomber sur le
        "Page N" par defaut de GTK.

        Depuis la conversion de Whost en construction Python pure (plus de
        Gtk.Builder), cette classe de bug ne peut plus se produire : les
        pages sont ajoutees directement dans nbHost, dans l'ordre et avec
        le bon libelle (cf. __init__). Cette methode est conservee par
        prudence plutot que supprimee -- elle ne fait plus que reaffirmer
        un etat deja correct (reorder_child/set_tab_label_text sur des
        pages deja bien placees), un no-op inoffensif.

        Args:
            (none)
        """
        _loguru_logger.debug("_fix_host_notebook_pages: entrée")
        nb = self.get_widget("nbHost")
        if nb is None:
            _loguru_logger.debug("_fix_host_notebook_pages: sortie")
            return
        for index, (widget_id, label) in enumerate(self._HOST_NOTEBOOK_PAGES):
            page = self.get_widget(widget_id)
            if page is None:
                continue
            nb.reorder_child(page, index)
            if label:
                nb.set_tab_label_text(page, _(label))
        _loguru_logger.debug("_fix_host_notebook_pages: fin")

    def _update_host_tabs_for_type(self, proto):
        """Affiche/masque les onglets du dialogue Edit Host selon le protocole.

        Seul l'onglet Properties est toujours visible. Les onglets propres
        a SSH (Advanced SSH, Port forwarding, SSHFS) ne sont montres que
        pour proto == "ssh". Les onglets Colors and Keys / Commands, qui ne
        s'appliquent qu'aux protocoles utilisant un terminal VTE (ssh,
        telnet, local, serial, ipmi), sont montres pour ce groupe. Chaque
        onglet dedie a un protocole graphique (RDP/VNC/SPICE) ou au web
        n'est montre que pour ce protocole precis, et Serial uniquement
        pour serial.

        Args:
            proto (str): Valeur active de cmbType ("ssh", "rdp", "vnc",
                "spice", "serial", "ipmi", "web", "telnet" ou "local").
        """
        _loguru_logger.debug("_update_host_tabs_for_type: entrée")
        vte_protocols = {"ssh", "telnet", "local", "serial", "ipmi"}
        is_vte = proto in vte_protocols

        visibility = {
            "swHostColorsKeys": is_vte,
            "swHostCommands": is_vte,
        }
        for plugin_proto, attr_name in self._PLUGIN_TAB_ATTRS.items():
            if plugin_proto == "ssh":
                continue
            visibility[attr_name] = proto == plugin_proto
        for widget_id, visible in visibility.items():
            page = self.get_widget(widget_id)
            if page is not None:
                page.set_visible(visible)

        # Onglet SSH : une seule page plugin (fusionne les anciennes pages
        # Advanced SSH/Port forwarding/SSHFS, sous-onglets internes).
        self._plugin_page["ssh"].set_visible(proto == "ssh")
        _loguru_logger.debug("_update_host_tabs_for_type: fin")

