    # -- Whost.on_okbutton1_clicked {
    def on_okbutton1_clicked(self, widget, *args):
        """Gestionnaire du bouton OK / Valider.

        Args:
            widget (Gtk.Button): Bouton clique.
            *args: Arguments supplémentaires.
        """
        _loguru_logger.debug("on_okbutton1_clicked: entrée")
        group_txt = self.cmbGroup.get_active_text()
        if (
            not group_txt
            and self.cmbGroup.get_has_entry()
            and self.cmbGroup.get_child() is not None
        ):
            group_txt = self.cmbGroup.get_child().get_text()
        # Fallback sur la valeur stockée à l'init (cmbGroup peut être insensible)
        if not group_txt and hasattr(self, "_group_value"):
            group_txt = self._group_value
        group = (group_txt or "").strip()
        name = self.txtName.get_text().strip()
        description = self.txtDescription.get_text().strip()
        host = self.txtHost.get_text().strip()
        ctype = (self.cmbType.get_active_id() or "").strip()
        user = self.txtUser.get_text().strip()
        password = self.txtPass.get_text().strip()
        private_key = self.txtPrivateKey.get_text().strip()
        port = self.txtPort.get_text().strip()
        buf = self.txtCommands.get_buffer()
        commands = (
            buf.get_text(buf.get_start_iter(), buf.get_end_iter(), False).strip()
            if self.chkCommands.get_active()
            else ""
        )
        if self.get_widget("chkDefaultColors").get_active():
            fcolor = ""
            bcolor = ""
        else:
            fcolor = color_to_hex(self.btnFColor.get_rgba())
            bcolor = color_to_hex(self.btnBColor.get_rgba())

        log = self.chkLogging.get_active()
        backspace_key = self.cmbBackspace.get_active()
        delete_key = self.cmbDelete.get_active()
        auto_close_tab = self._AUTO_CLOSE_TAB_VALUES[self.cmbAutoCloseTab.get_active()]
        workspace = self.chkWorkspace.get_active()
        pre_connect_command = self.txtPreConnectCommand.get_text().strip()
        post_connect_command = self.txtPostConnectCommand.get_text().strip()

        if ctype == "":
            ctype = "ssh"

        # Validar datos
        if group == "" or name == "" or (host == "" and ctype != "local"):
            msgbox(_("Fields group, name and host are required"))
            _loguru_logger.debug("on_okbutton1_clicked: sortie")
            return

        if ctype != "local" and not (port and port.isdigit() and 1 <= int(port) <= 65535):
            msgbox(_("Invalid port"))
            _loguru_logger.debug("on_okbutton1_clicked: sortie")
            return

        term = self.txtTerm.get_text()
        protocol = (
            self.cmbProtocol.get_active_id().strip()
            if hasattr(self, "cmbProtocol") and self.cmbProtocol.get_active_id()
            else "ssh"
        )

        # ── Champs core, communs à tous les protocoles ──────────────────────
        host = Host(
            group=group,
            name=name,
            description=description,
            host=host,
            user=user,
            password=password,
            private_key=private_key,
            port=port,
            type=ctype,
            commands=commands,
            font_color=fcolor,
            back_color=bcolor,
            log=log,
            backspace_key=backspace_key,
            delete_key=delete_key,
            term=term,
            protocol=protocol,
            auto_close_tab=auto_close_tab,
            workspace=workspace,
            pre_connect_command=pre_connect_command,
            post_connect_command=post_connect_command,
        )

        # ── Champs spécifiques à chaque protocole ───────────────────────────
        # Chaque plugin lit directement sa propre page dans le Host final —
        # aucun protocole ni champ protocole-spécifique n'est jamais nommé
        # ici, l'application découvre tout via plugin_registry.
        for plugin in wMain.plugin_registry.all():
            plugin.save_host_fields(host)

        # Le tri du port forwarding par la page SSH (ancien code Glade) est
        # historiquement affiché en ordre inverse d'ajout pour ce protocole.
        if ctype == "ssh":
            host.tunnel = list(reversed(host.tunnel))

        app_logger.debug(
            f"Whost.on_okbutton1_clicked | ssh_sshfs_mount="
            f"{getattr(host, 'ssh_sshfs_mount', None)}"
        )

        try:
            # Guardar
            if group not in groups:  # not groups.has_key(group):
                groups[group] = []

            if self.isNew:
                for h in groups[group]:
                    if h.name == name:
                        msgbox(
                            "%s [%s] %s [%s]"
                            % (
                                _("Host name"),
                                name,
                                _("already exists for group"),
                                group,
                            )
                        )
                        _loguru_logger.debug("on_okbutton1_clicked: sortie")
                        return
                # agregar host a grupo
                groups[group].append(host)
            else:
                if self.oldGroup != group:
                    # revisar que no este el nombre en el nuevo grupo
                    if group not in groups:  # if not groups.has_key(group):
                        groups[group] = [host]
                    else:
                        for h in groups[group]:
                            if h.name == name:
                                msgbox(
                                    "%s [%s] %s [%s]"
                                    % (
                                        _("Host name"),
                                        name,
                                        _("already exists for group"),
                                        group,
                                    )
                                )
                                _loguru_logger.debug("on_okbutton1_clicked: sortie")
                                return
                        groups[group].append(host)
                        for h in groups[self.oldGroup]:
                            if h.name == self.oldName:
                                groups[self.oldGroup].remove(h)
                                break
                else:
                    if self.oldName != name:
                        for h in groups[self.oldGroup]:
                            if h.name == name:
                                msgbox(
                                    "%s [%s] %s [%s]"
                                    % (
                                        _("Host name"),
                                        name,
                                        _("already exists for group"),
                                        group,
                                    )
                                )
                                _loguru_logger.debug("on_okbutton1_clicked: sortie")
                                return
                        for h in groups[self.oldGroup]:
                            if h.name == self.oldName:
                                index = groups[self.oldGroup].index(h)
                                groups[self.oldGroup][index] = host
                                break
                    else:
                        for h in groups[self.oldGroup]:
                            if h.name == self.oldName:
                                index = groups[self.oldGroup].index(h)
                                groups[self.oldGroup][index] = host
                                break
        except BaseException as exc:
            _loguru_logger.error("sauvegarde de l'hôte impossible : {}", exc)
            msgbox("%s [%s]" % (_("Error saving host. Description"), sys.exc_info()[1]))

        wMain.updateTree()
        wMain.writeConfig()

        self.request_close()
        _loguru_logger.debug("on_okbutton1_clicked: fin")

