    def addParam(self, name, field, ptype, *args):
        """Ajoute un parametre dans le tableau de parametres.

        Args:
            name (str): Nom du parametre.
            field (str): Champ associé au parametre.
            ptype (type): Type du parametre.
            *args: Arguments supplémentaires.
        """
        _loguru_logger.debug("addParam: entrée")
        x = self.tblGeneral.rows
        self.tblGeneral.rows += 1
        value = eval(field)
        if ptype == bool:
            obj = Gtk.CheckButton()
            obj.set_label(name)
            obj.set_active(value)
            obj.set_halign(Gtk.Align.START)
            obj.show()
            obj.field = field
            self.tblGeneral.attach(
                obj,
                0,
                2,
                x,
                x + 1,
                Gtk.AttachOptions.EXPAND | Gtk.AttachOptions.FILL,
                0,
            )
        elif ptype == int:
            obj = Gtk.SpinButton(climb_rate=10)
            if len(args) == 2:
                obj.set_range(args[0], args[1])
            obj.set_increments(1, 10)
            obj.set_numeric(True)
            obj.set_value(value)
            obj.show()
            obj.field = field
            lbl = Gtk.Label(label=name)
            lbl.set_xalign(0.0)
            lbl.show()
            self.tblGeneral.attach(lbl, 0, 1, x, x + 1, Gtk.AttachOptions.FILL, 0)
            self.tblGeneral.attach(
                obj,
                1,
                2,
                x,
                x + 1,
                Gtk.AttachOptions.EXPAND | Gtk.AttachOptions.FILL,
                0,
            )
        elif ptype == list:
            obj = Gtk.ComboBoxText()
            for s in args[0]:
                obj.append_text(s)
            obj.set_active(value)
            obj.show()
            obj.field = field
            lbl = Gtk.Label(label=name)
            lbl.set_xalign(0.0)
            lbl.show()
            self.tblGeneral.attach(lbl, 0, 1, x, x + 1, Gtk.AttachOptions.FILL, 0)
            self.tblGeneral.attach(
                obj,
                1,
                2,
                x,
                x + 1,
                Gtk.AttachOptions.EXPAND | Gtk.AttachOptions.FILL,
                0,
            )
        else:
            obj = Gtk.Entry()
            obj.set_text(value)
            obj.show()
            obj.field = field
            lbl = Gtk.Label(label=name)
            lbl.set_xalign(0.0)
            lbl.show()
            self.tblGeneral.attach(lbl, 0, 1, x, x + 1, Gtk.AttachOptions.FILL, 0)
            self.tblGeneral.attach(
                obj,
                1,
                2,
                x,
                x + 1,
                Gtk.AttachOptions.EXPAND | Gtk.AttachOptions.FILL,
                0,
            )
        _loguru_logger.debug("addParam: fin")

    def on_edited(self, widget, rownum, value, model, colnum):
        """Gestionnaire de fin d'edition d'une cellule.

        Args:
            widget (Gtk.CellRenderer): Renderer source.
            rownum (int): Numero de la ligne de la cellule.
            value (str): Nouveau texte de la cellule.
            model (Gtk.TreeModel): Modele de la cellule.
            colnum (int): Numero de la colonne.
        """
        _loguru_logger.debug("on_edited: entrée")
        model[rownum][colnum] = value
        if model == self.treeModel2:
            i = self.treeModel2.get_iter_first()
            while i is not None:
                j = self.treeModel2.iter_next(i)
                self.treeModel2[i]
                if self.treeModel2[i][0] == self.treeModel2[i][1] == "":
                    self.treeModel2.remove(i)
                i = j
            self.treeModel2.append(None, ["", ""])
            if self.capture_keys:
                self.capture_keys = False
        _loguru_logger.debug("on_edited: fin")

    def on_editing_started(self, widget, entry, rownum, model, colnum):
        """Gestionnaire de debut d'edition d'une cellule.

        Args:
            widget (Gtk.CellRenderer): Renderer source.
            entry (Gtk.CellEditable): Widget editable.
            rownum (int): Numero de la ligne de la cellule.
            model (Gtk.TreeModel): Modele de la cellule.
            colnum (int): Numero de la colonne.
        """
        _loguru_logger.debug("on_editing_started: entrée")
        self.capture_keys = True
        entry.connect(
            "key-press-event",
            self.on_treeCommands_key_press_event,
            model,
            rownum,
            colnum,
        )
        _loguru_logger.debug("on_editing_started: fin")

