    def on_okbutton1_clicked(self, widget, *args):
        """Gestionnaire du bouton OK / Valider.

        Args:
            widget (Gtk.Button): Bouton clique.
            *args: Arguments supplémentaires.
        """
        _loguru_logger.debug("on_okbutton1_clicked: entrée")
        for obj in self.tblGeneral:
            if hasattr(obj, "field"):
                if isinstance(obj, Gtk.CheckButton):
                    value = obj.get_active()
                elif isinstance(obj, Gtk.SpinButton):
                    value = obj.get_value_as_int()
                elif isinstance(obj, Gtk.ComboBox):
                    value = obj.get_active()
                else:
                    value = '"%s"' % (obj.get_text())
                exec("%s=%s" % (obj.field, value))

        if self.chkDefaultColors1.get_active():
            conf.FONT_COLOR = ""
            conf.BACK_COLOR = ""
        else:
            conf.FONT_COLOR = self.btnFColor.selected_color
            conf.BACK_COLOR = self.btnBColor.selected_color

        if (
            self.btnFont.selected_font.to_string() != "monospace"
            and not self.chkDefaultFont.get_active()
        ):
            conf.FONT = self.btnFont.selected_font.to_string()
        else:
            conf.FONT = ""

        # Guardar shortcuts
        scuts = {}
        for x in self.treeModel:
            if x[0] != "" and x[1] != "":
                scuts[x[1]] = [x[0]]
        for x in self.treeModel2:
            if x[0] != "" and x[1] != "":
                scuts[x[1]] = x[0]
        global shortcuts
        shortcuts = scuts

        # Update servers window colors
        wMain.updateTree()

        # Recrear menu de comandos personalizados
        wMain.popupMenu.populate_commands(select_command_shortcuts(shortcuts))
        # Sauvegarder les préférences plugin (Libvirt/Proxmox/VirtualBox...)
        for _prefs_tab in getattr(self, "_plugin_prefs_tabs", []):
            if hasattr(_prefs_tab, "apply"):
                _prefs_tab.apply()
        if hasattr(self, "_serial_tpl_prefs"):
            self._serial_tpl_prefs.apply()

        wMain.writeConfig()

        self.request_close()
        _loguru_logger.debug("on_okbutton1_clicked: fin")

