class Wcluster(GCMBase, Gtk.Dialog):
    """Dialogue Cluster — troisième écran converti du Glade vers Python pur.

    Écran 100% Python (plus de chargement de ``wCluster`` depuis
    ``gnome-connection-manager.glade``) : hérite directement de
    ``Gtk.Dialog`` (mode ``path=None`` de ``GCMBase``, même pattern que
    ``Wabout``/``Wmain``).

    Reconstruction fidèle de l'arbre de widgets défini par le noeud
    ``wCluster`` du ``.glade`` : la zone de contenu standard d'un
    ``Gtk.Dialog`` (``get_content_area()``) contient d'abord la barre de
    boutons Execute/Close (``action_area``, en position 0 — ordre
    inhabituel mais bien celui d'origine dans le ``.glade``, boutons
    au-dessus du contenu et non en dessous), puis le contenu principal
    (``treeHosts``, boutons Tout sélectionner/Tout désélectionner/Inverser,
    zone de commandes ``txtCommands1``).

    Fidélité : le ``.glade`` d'origine ne déclarait aucune propriété
    ``transient-for`` sur ``wCluster`` (contrairement à ``Wabout``, où
    ``set_transient_for`` avait été ajouté explicitement) — l'argument
    ``parent`` que l'ancien constructeur transmettait à ``GCMBase`` n'avait
    d'ailleurs aucun effet en dehors du chargement Glade par ``root``
    (seulement utilisé pour ``builder.expose_object``, jamais déclenché
    ici). Ce comportement (absence de transience explicite) est conservé
    tel quel.

    Seuls deux identifiants du sous-arbre ``wCluster`` étaient consultés
    ailleurs dans la classe via ``self.get_widget(...)`` (``treeHosts`` et
    ``txtCommands1``) : plutôt que de garder un ``get_widget`` générique
    pour seulement deux usages, ils sont maintenant des attributs directs
    (``self.treeHosts`` / ``self.txtCommands1``), et les deux appels
    correspondants ont été mis à jour en conséquence.
    """

    def __init__(self, terms=None, show=True, **kwargs):
        """Construit le dialogue cluster (widgets, signaux, état).

        Args:
            terms: Liste de tuples (titre, terminal VTE) à proposer dans
                la liste des hôtes du cluster.
            show (bool): Si False, ne pas afficher le dialogue (utilisé
                pour l'ouverture en onglet épinglé, cf.
                Wmain.open_management_tab).
            **kwargs: Arguments supplémentaires.
        """
        _loguru_logger.debug("__init__: entrée")
        Gtk.Dialog.__init__(self)
        GCMBase.__init__(self, path=None, **kwargs)
        self.main_widget = self
        self.terms = terms

        self.set_title(_("Cluster"))
        self.set_modal(True)
        self.set_default_size(640, 480)
        self.set_type_hint(Gdk.WindowTypeHint.DIALOG)
        if getattr(wMain, "window", None) is not None:
            self.set_transient_for(wMain.window)

        content_area = self.get_content_area()
        content_area.set_spacing(2)

        action_area = Gtk.ButtonBox(orientation=Gtk.Orientation.HORIZONTAL)
        action_area.set_layout(Gtk.ButtonBoxStyle.END)
        action_area.set_spacing(6)
        action_area.show()
        content_area.pack_start(action_area, False, False, 0)

        btnExecuteCluster = Gtk.Button(label=_("Execute"))
        btnExecuteCluster.set_receives_default(True)
        btnExecuteCluster.set_tooltip_text(
            _("Send the command above to every checked host (same as pressing Enter)")
        )
        btnExecuteCluster.show()
        btnExecuteCluster.connect("clicked", self.on_btnExecuteCluster_clicked)
        action_area.add(btnExecuteCluster)

        cancelbutton2 = Gtk.Button(label=_("Close"))
        cancelbutton2.set_receives_default(True)
        cancelbutton2.show()
        cancelbutton2.connect("clicked", self.on_cancelbutton2_clicked)
        action_area.add(cancelbutton2)

        main_box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL)
        main_box.show()
        content_area.pack_start(main_box, False, True, 0)

        lbl_select = Gtk.Label(label=_("Select consoles to use:"))
        lbl_select.set_halign(Gtk.Align.START)
        lbl_select.show()
        main_box.pack_start(lbl_select, False, True, 0)

        hosts_row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL)
        hosts_row.show()
        main_box.pack_start(hosts_row, False, True, 0)

        scrolled = Gtk.ScrolledWindow()
        scrolled.set_hexpand(True)
        scrolled.set_shadow_type(Gtk.ShadowType.IN)
        scrolled.show()
        self.treeHosts = Gtk.TreeView()
        self.treeHosts.set_hexpand(True)
        self.treeHosts.set_vexpand(True)
        self.treeHosts.show()
        scrolled.add(self.treeHosts)
        hosts_row.pack_start(scrolled, False, True, 0)

        def _icon_label_button(stock_id, label_text):
            """Reconstruit un bouton "icone + libelle" (GtkAlignment >
            GtkBox > GtkImage + GtkLabel), tel que genere par le .glade
            d'origine pour btnAll/btnNone/btnInvert.

            """
            _loguru_logger.debug("Wcluster._icon_label_button: entrée")
