class CheckUpdates(Thread):
    """Vérifie les mises à jour de l'application GCM.

    Keyword Arguments:
    parent -- Widget parent pour les notifications.
    """

    def __init__(self, p):
        """Initialise l'instance.

        Args:
            p: Parametre p.
        """
        _loguru_logger.debug("__init__: entrée")
        Thread.__init__(self)
        self.parent = p
        _loguru_logger.debug("__init__: fin")

    def msg(self, text, parent):
        """Envoie une notification.

        Args:
            text (str): Texte de la notification.
            parent: Widget parent pour la notification.
        """
        _loguru_logger.debug("msg: entrée")
        self.msgBox = Gtk.MessageDialog(
            parent=parent,
            modal=True,
            message_type=Gtk.MessageType.ERROR,
            buttons=Gtk.ButtonsType.OK,
            text=text,
        )
        self.msgBox.set_icon_from_file(ICON_PATH)
        self.msgBox.connect("response", self.on_clicked)
        self.msgBox.show_all()
        _loguru_logger.debug("msg: sortie")
        return False

    def on_clicked(self, *args):
        """Gestionnaire de clic sur la notification.

        Args:
            *args: Arguments supplémentaires.
        """
        _loguru_logger.debug("on_clicked: entrée")
        self.msgBox.destroy()
        _loguru_logger.debug("on_clicked: fin")

    def run(self):
        """Execute la boucle de notifications."""
        _loguru_logger.debug("run: entrée")
        try:
            import socket
            import urllib.request as urllib

            socket.setdefaulttimeout(5)
            web = urllib.urlopen(
                "https://raw.githubusercontent.com/MathildeDec/"
                "gnome-connection-manager/develop/_current.html"
            )
            if web.getcode() == 200:
                new_version = web.readline().strip().decode("utf-8")
                if len(new_version) > 0 and new_version > app_version:
                    self.tag = GLib.timeout_add(
                        0,
                        self.msg,
                        "%s\n\nCURRENT VERSION: %s\nNEW VERSION: %s"
                        % (
                            _(
                                "A new version is available: https://"
                                "github.com/MathildeDec/gnome-connection-manager/releases"
                            ),
                            app_version,
                            new_version,
                        ),
                        self.parent.get_widget("wMain"),
                    )
        except Exception as exc:
            _loguru_logger.debug("vérification de nouvelle version impossible : {}", exc)
        _loguru_logger.debug("run: fin")


